  fr.onload=()=>{setTimeout(()=>{try{fr.contentWindow.focus();fr.contentWindow.print();}catch(err){const w=window.open("","_blank");if(w){w.document.write(html);w.document.close();w.focus();w.print();}}setTimeout(()=>fr.remove(),60000);},250);};
