// Ready for departure: what MSS has actioned, plus the FD's own 2nd Note instructions to check against
const CARE_ITEM_RE=/shroud|crucifix|cross|name plate|hair|capri|dressing|viewing room|gravemarker|coffin packaging/i;
function plateWording(np, c){
  if(!np) return ""; if(np.none) return "Not required";
  const pl=np.plate; if(!pl) return np.at?"Engraved":"";
  const pe=np.person||c, nm=plateName({...pl,firstName:pe.firstName,lastName:pe.lastName});
  const parts=[pl.show?.name&&nm&&nm.toUpperCase(),pl.show?.name&&pl.nativeName,pl.show?.dates&&(pl.dateMode==="age"?(npAge(pe.dob,pe.dod)!==""?`${npAge(pe.dob,pe.dod)} YEARS`:""):[npDate(pe.dob),npDate(pe.dod)].filter(Boolean).join(" – ")),pl.show?.message&&pl.message,pl.show?.message&&pl.message2].filter(Boolean);
  const kind=[FINISHES[pl.finish]?.label,(PLATES[pl.size]||{}).label].filter(Boolean).join(" ");
  return `${kind?kind+" – ":""}"${parts.join(" · ")}"${np.at?" – engraved":""}`;
}
function buildCompletedEmail(c, prep, billable, otherUsed, noteLines) {
  const done=[];
  const prepList=(prep.prepOptions||[]).join(", ");
  if(prepList) done.push(`Body preparation: ${prepList}`);
  const treat=["Aspiration","Cavity Treatment","Bio-Seal"].filter(k=>otherUsed?.[k]);
  if(treat.length) done.push(`Treatment: ${treat.join(", ")}`);
  const items=Object.keys(billable||{}).filter(k=>billable[k]&&CARE_ITEM_RE.test(k));
  if(items.length) done.push(`Care items: ${items.join(", ")}`);
  const pw=plateWording(prep.namePlate,c); if(pw) done.push(`Name plate: ${pw}`);
  if(prep.viewing==="Yes") done.push(`Viewing: Yes${prep.viewingLocation?" — "+prep.viewingLocation:""}${prep.viewingHost?" (Hosted by "+prep.viewingHost+")":""}${fullSlot(prep)?" @ "+fmtDayLong(fullSlot(prep).split("_")[0])+" "+fullSlot(prep).split("_")[1]:""}`);
  done.push(`Valuables: ${c.valuables||"Nil"}`);
  const col=[prep.collectionDate&&fmtDayLong(prep.collectionDate),prep.collectionTime].filter(Boolean).join(", ");
  const fun=[prep.funeralDate&&fmtDayLong(prep.funeralDate),prep.funeralTime].filter(Boolean).join(", ");
  return `Hi ${c.funeralHomeName} Team,

Just to let you know that ${c.firstName} ${c.lastName} is ready for departure. The items below have been actioned by the MSS team. Please check them against your instructions, and call us before collection if anything is missing or not as you asked.

DECEASED DETAILS
Name: ${c.firstName} ${c.lastName}
DOB: ${fmt(c.dob)} | DOD: ${fmt(c.dod)}
Case Reference: ${c.caseRef}

WHAT WE HAVE DONE
${done.join("\n")}
${noteLines&&noteLines.length?`
YOUR 2ND NOTE INSTRUCTIONS
${noteLines.join("\n")}
`:""}
COLLECTION
Collection: ${col||"—"}
Disposition: ${prep.disposition||"—"}
Funeral: ${fun||"—"}${prep.comments?`
Comments: ${prep.comments}`:""}

PAPERWORK
Paperwork: ${c.paperwork||"None"}

Please contact us to arrange collection, or if anything above needs to change.${MSS_FOOTER}`;
}

