// Photo picked from a phone/computer -> smaller JPEG (base64) for the auto-read
function imgToJpeg(file){return new Promise((res,rej)=>{const u=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const s=Math.min(1,1568/Math.max(img.width,img.height));const cv=document.createElement("canvas");cv.width=Math.round(img.width*s);cv.height=Math.round(img.height*s);cv.getContext("2d").drawImage(img,0,0,cv.width,cv.height);URL.revokeObjectURL(u);res(cv.toDataURL("image/jpeg",0.85).split(",")[1]);};img.onerror=()=>{URL.revokeObjectURL(u);rej(new Error("image"));};img.src=u;});}

// iPhone HEIC photo -> JPEG, so every browser can read it and FDs can open it
async function heicToJpeg(file){
  if(!/heic|heif/i.test(file.type)&&!/\.(heic|heif)$/i.test(file.name)) return file;
  if(!window.heic2any) await new Promise((res,rej)=>{const s=document.createElement("script");s.src="https://cdn.jsdelivr.net/npm/heic2any@0.0.4/dist/heic2any.min.js";s.onload=res;s.onerror=rej;document.head.appendChild(s);});
  let out=await window.heic2any({blob:file,toType:"image/jpeg",quality:0.9});
  if(Array.isArray(out)) out=out[0];
  return new File([out],file.name.replace(/\.(heic|heif)$/i,"")+".jpg",{type:"image/jpeg"});
}

// Several photos picked at once -> one multi-page PDF
async function imagesToPdf(files){
  const { PDFDocument } = await import("https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.esm.min.js");
  const doc=await PDFDocument.create();
  for(const file of files){
    const {url,w,h}=await new Promise((res,rej)=>{const u=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const s=Math.min(1,2200/Math.max(img.width,img.height));const cv=document.createElement("canvas");cv.width=Math.round(img.width*s);cv.height=Math.round(img.height*s);cv.getContext("2d").drawImage(img,0,0,cv.width,cv.height);URL.revokeObjectURL(u);res({url:cv.toDataURL("image/jpeg",0.85),w:cv.width,h:cv.height});};img.onerror=()=>{URL.revokeObjectURL(u);rej(new Error("image"));};img.src=u;});
    const jpg=await doc.embedJpg(Uint8Array.from(atob(url.split(",")[1]),ch=>ch.charCodeAt(0)));
    const land=w>h,W=land?841.89:595.28,H=land?595.28:841.89,k=Math.min((W-20)/w,(H-20)/h);
    doc.addPage([W,H]).drawImage(jpg,{x:(W-w*k)/2,y:(H-h*k)/2,width:w*k,height:h*k});
  }
  return new File([await doc.save()],"pages.pdf",{type:"application/pdf"});
}

// ─── CHECK IN ─────────────────────────────────────────────────────────────────
function CheckInFlow({user,cases,onComplete,onUpdateCase,onBack}) {
  const [step,setStep]=useState(1);
  const [completing,setCompleting]=useState(null);
  const [part,setPart]=useState(false);
  const [showPart,setShowPart]=useState(false);
  const [checkinRole,setCheckinRole]=useState(user?.role==="fd"?"FUNERAL DIRECTOR":user?.role==="transfer"?"TRANSFER TEAM":"");
  const canPart=["mss","admin","transfer","fd"].includes(user?.role)||(user?.role==="guest"&&["MSS","TRANSFER TEAM","FUNERAL DIRECTOR"].includes(checkinRole));
  const [selFH,setSelFH]=useState(user?.role==="fd"?user.funeralHomeId:null);
  const [otherFHName,setOtherFHName]=useState("");
  const [errors,setErrors]=useState({});
  const [submitted,setSubmitted]=useState(null);
  const [emailOpened,setEmailOpened]=useState(false);
  const [labelPrinted,setLabelPrinted]=useState(false);
  const [saving,setSaving]=useState(false);
  useEffect(()=>{if(submitted)window.scrollTo({top:0,behavior:"smooth"});},[submitted]);
  const [scanOpen,setScanOpen]=useState(false);
  const [ocr,setOcr]=useState({status:"",msg:""});
  const formRef=React.useRef(null);
  const lastScanRef=React.useRef(null);
  const READ_LABELS=["MCCD","Coroners BO","LE","VOD"];
  const DOC_NAME={MCCD:"MCCD","Coroners BO":"BO (Coroner's)",LE:"Life Extinct (LE)",VOD:"VOD",CRA:"CRA",Other:"different document",OTHER:"other document"};
  const [noDeathDoc,setNoDeathDoc]=useState(false);
  const [scanPick,setScanPick]=useState("");
  const [ciManual,setCiManual]=useState(false);
  useEffect(()=>{if(ocr.status&&ocr.status!=="reading")document.getElementById("ocr-banner")?.scrollIntoView({behavior:"smooth",block:"center"});},[ocr.status]);
  const pwOf=l=>l==="Coroners BO"?"BO":l;
  function relabelDoc(doc,newLabel){
    setForm(f=>{
      const docs=(f.checkInDocs||[]).map(d=>d===doc?{...d,label:newLabel}:d);
      let pw=f.paperwork.filter(p=>p!==pwOf(doc.label)||docs.some(d=>pwOf(d.label)===p));
      if(PAPERWORK_OPTIONS.includes(pwOf(newLabel))&&!pw.includes(pwOf(newLabel))) pw=[...pw,pwOf(newLabel)];
      return {...f,checkInDocs:docs,paperwork:pw};
    });
  }
  async function readDocument(images,label,pdf,pdfUrl){
    setOcr({status:"reading",msg:`Reading ${DOC_NAME[label]||label}…`});
    const ctl=new AbortController();const t=setTimeout(()=>ctl.abort(),pdfUrl?55000:25000);
    try{
      const r=await fetch("/api/read-document",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(pdfUrl?{label,pdfUrl}:pdf?{label,pdf}:{label,images}),signal:ctl.signal});
      const j=await r.json().catch(()=>({}));
      if(r.status===503){setOcr({status:"off",msg:"Auto-read isn't switched on yet. The document was saved — please type the details."});return;}
      if(!r.ok) throw new Error(j.error||("Error "+r.status));
      const det=j.docType||"";
      const LEVOD_SAME=["LE","VOD"].includes(det)&&["LE","VOD"].includes(label); // "Verification of Life Extinct" forms are both
      if(det&&det!==label&&!LEVOD_SAME&&det!=="Other"){setOcr({status:"confirm",label,detected:det,fields:j.fields||{},doc:lastScanRef.current});return;}
      applyRead(j.fields||{},label);
    }catch(e){
      setOcr({status:"error",msg:e.name==="AbortError"?"Reading took too long. The document was saved — please type the details.":"Couldn't read the document ("+e.message+"). It was saved — please type the details."});
    }finally{clearTimeout(t);}
  }
  async function ciUpload(fileList){
    let files=Array.from(fileList||[]);
    if(!files.length||!scanLabel) return;
    if(files.some(x=>/heic|heif/i.test(x.type)||/\.(heic|heif)$/i.test(x.name))){
      setOcr({status:"reading",msg:"Converting iPhone photo…"});
      files=await Promise.all(files.map(x=>heicToJpeg(x).catch(()=>x)));
      setOcr({status:"",msg:""});
    }
    const isImg=x=>/^image\//.test(x.type)&&!/\.pdf$/i.test(x.name);
    let readImgs=null;
    if(files.length>1){
      const imgs=files.filter(isImg),pdfs=files.filter(x=>!isImg(x));
      if(imgs.length>1){
        try{ if(READ_LABELS.includes(scanLabel)) readImgs=await Promise.all(imgs.slice(0,3).map(imgToJpeg)); }catch(e){}
        let combined;try{combined=await imagesToPdf(imgs);}catch(e){combined=null;}
        if(combined){ for(const p of pdfs) await ciUpload1(p,false); return ciUpload1(combined,true,readImgs); }
      }
      for(let i=0;i<files.length;i++) await ciUpload1(files[i],i===0);
      return;
    }
    return ciUpload1(files[0],true);
  }
  async function ciUpload1(file,doRead=true,readImgs=null){
    if(!file||!scanLabel) return;
    const lbl=scanLabel;
    const safe=s=>String(s||"").replace(/[^a-zA-Z0-9]/g,"_");
    const fhName=FUNERAL_HOMES.find(f=>f.id===(isFD?user.funeralHomeId:selFH))?.name;
    const isPdf=file.type==="application/pdf"||/\.pdf$/i.test(file.name);
    const ext=isPdf?".pdf":((file.name.match(/\.[a-z0-9]+$/i)||[".jpg"])[0].toLowerCase());
    const name=(`${safe(fhName||"FD")}_${safe(form.lastName||"Unknown")}_${form.dod?form.dod.split("-").reverse().join(""):""}`).replace(/_$/,"")+ext;
    const named=new File([file],name,{type:file.type||(isPdf?"application/pdf":"image/jpeg")});
    setScanPick("");
    setForm(f=>{const pw=pwOf(lbl);return{...f,checkInDocs:[...(f.checkInDocs||[]),(lastScanRef.current={label:lbl,name,file:named})],paperwork:PAPERWORK_OPTIONS.includes(pw)&&!f.paperwork.includes(pw)?[...f.paperwork,pw]:f.paperwork};});
    if(!doRead||!READ_LABELS.includes(lbl)) return;
    try{
      if(readImgs&&readImgs.length){readDocument(readImgs,lbl);return;}
      if(isPdf){
        if(file.size>3*1024*1024){
          // Too big to send directly: put a temporary copy in storage and let the reader fetch it
          if(file.size>30*1024*1024){setOcr({status:"none",msg:"The PDF was saved, but it is over 30 MB, too large to read automatically. Please type the details."});return;}
          setOcr({status:"reading",msg:`Reading ${DOC_NAME[lbl]||lbl} (large PDF, this can take up to a minute)…`});
          const tmp=`tmp-read/${Date.now()}_${Math.random().toString(36).slice(2)}.pdf`;
          const up=await fetch(`${SUPABASE_URL}/storage/v1/object/${STORAGE_BUCKET}/${tmp}`,{method:"POST",headers:{apikey:SUPABASE_KEY,Authorization:"Bearer "+SUPABASE_KEY,"Content-Type":"application/pdf","x-upsert":"true"},body:file});
          if(!up.ok){setOcr({status:"none",msg:"The PDF was saved, but it couldn't be sent for reading. Please type the details."});return;}
          try{await readDocument(null,lbl,null,getDocumentUrl(tmp));}finally{deleteDocument(tmp).catch(()=>{});}
          return;
        }
        const b64=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(",")[1]);r.onerror=rej;r.readAsDataURL(file);});
        readDocument(null,lbl,b64);
      }else{
        readDocument([await imgToJpeg(file)],lbl);
      }
    }catch(e){setOcr({status:"error",msg:"Couldn't open that file to read it. It was saved — please type the details."});}
  }
  function applyRead(fl,label){
    {const names={firstName:"first name",lastName:"last name",dob:"DOB",dod:"DOD",sex:"sex",transferFrom:"transferred from"};
      const f=formRef.current||{};const u={};
        ["firstName","lastName","dob","dod","sex"].forEach(k=>{if(fl[k]&&!String(f[k]||"").trim()){u[k]=fl[k];}});
        if(u.dob&&u.dob>today()) delete u.dob; if(u.dod&&u.dod>today()) delete u.dod;
        if(label==="Coroners BO"&&!f.transferFrom){u.transferFrom="Coroners";u.transferFromSub=CORONER_OPTIONS.includes(fl.coronerOffice)?fl.coronerOffice:"Sydney";}
        else if(label!=="Coroners BO"&&!f.transferFrom&&(fl.placeType||fl.placeOfDeath)){
          const type=TRANSFER_FROM_OPTIONS.includes(fl.placeType)?fl.placeType:"Other";
          u.transferFrom=type;u.transferFromSub=type==="Home"?"":(fl.placeOfDeath||"");
        }
      const filled=Object.keys(u).filter(k=>names[k]).map(k=>names[k]);
      const seen=[fl.firstName||fl.lastName?`${fl.firstName||""} ${fl.lastName||""}`.trim():"",fl.dob?"DOB "+fmt(fl.dob):"",fl.dod?"DOD "+fmt(fl.dod):"",fl.sex||"",fl.placeOfDeath||""].filter(Boolean);
      if(filled.length){setForm(p=>({...p,...u}));setErrors(e=>{const n={...e};Object.keys(u).forEach(k=>delete n[k]);return n;});}
      setOcr(filled.length
        ?{status:"done",msg:`Filled from ${DOC_NAME[label]||label}: ${filled.join(", ")}. Please check these against the document.`}
        :seen.length
          ?{status:"none",msg:`Read from the ${DOC_NAME[label]||label}: ${seen.join(", ")}. These boxes were already filled in, so nothing was changed. Please check they match.`}
          :{status:"none",msg:`Couldn't read the details clearly from the ${DOC_NAME[label]||label}. Please type them in.`});
    }
  }
  const [form,setForm]=useState({firstName:"",lastName:"",dob:"",dod:"",sex:"",transferFrom:"",transferFromSub:"",transferredBy:"",transferDate:today(),transferTime:new Date().toTimeString().slice(0,5),paperwork:[],nilVals:false,vals:false,valsText:"",otherItems:[],otherText:"",size:"",fridge:"",weight:"",pacemaker:false});
  formRef.current=form;
  function loadPart(x){
    const pc=x.prep?.partCheckIn||{};
    setCompleting(x);
    setForm({...{firstName:"",lastName:"",dob:"",dod:"",sex:"",transferFrom:"",transferFromSub:"",transferredBy:"",transferDate:today(),transferTime:new Date().toTimeString().slice(0,5),paperwork:[],nilVals:false,vals:false,valsText:"",otherItems:[],otherText:"",size:"",fridge:"",weight:"",pacemaker:false},...(pc.form||{}),checkInDocs:(pc.docs||[]).map(d=>({...d,existing:true}))});
    setSelFH(pc.selFH||x.funeralHomeId);setOtherFHName(pc.otherFHName||"");
    if(pc.checkinRole&&user?.role!=="transfer")setCheckinRole(pc.checkinRole);
    setNoDeathDoc(!!pc.noDeathDoc);setCiManual(!!pc.ciManual);
    setStep(3);window.scrollTo({top:0,behavior:"smooth"});
  }
  useEffect(()=>{if(!part&&_completePartId){const x=(cases||[]).find(k=>k.id===_completePartId);_completePartId=null;if(x)loadPart(x);}},[]);
  const deathDocDone=noDeathDoc||(form.checkInDocs||[]).some(d=>READ_LABELS.includes(d.label));
  const docLabel=p=>p==="BO"?"Coroners BO":p;
  const isScanned=p=>(form.checkInDocs||[]).some(d=>d.label===docLabel(p));
  const scanLabel=scanPick?docLabel(scanPick):"";
  const isFD=user?.role==="fd",isTransfer=user?.role==="transfer";
  const sortedFH=sortAlpha(FUNERAL_HOMES,"name");
  const isAllHoursOrMSS=!form.transferredBy||(form.transferredBy?.startsWith("All Hours")||form.transferredBy?.startsWith("MSS")||form.transferredBy?.startsWith("Statewide")||form.transferredBy==="ALL");
  useEffect(()=>{window.scrollTo({top:0,behavior:"smooth"});},[step]);

  function setF(k,v){setForm(f=>({...f,[k]:v}));setErrors(e=>({...e,[k]:""}))}
  function togglePW(p){setF("paperwork",form.paperwork.includes(p)?form.paperwork.filter(x=>x!==p):[...form.paperwork,p]);}
  function toggleOther(o){setF("otherItems",form.otherItems.includes(o)?form.otherItems.filter(x=>x!==o):[...form.otherItems,o]);}

  function getTransferDisplay(){
    if(!form.transferFrom) return "—";
    if(["Home","Repatriation"].includes(form.transferFrom)) return form.transferFrom;
    if(form.transferFrom==="Coroners") return `Coroners - ${form.transferFromSub||"Sydney"}`;
    return form.transferFromSub?`${form.transferFrom} - ${form.transferFromSub}`:form.transferFrom;
  }
  function getValuablesDisplay(){
    const parts=[];
    if(form.nilVals) parts.push("Nil");
    else if(form.vals) parts.push(form.valsText?`Valuables: ${form.valsText}`:"Valuables");
    if(form.otherItems.includes("ROSARY")) parts.push("Rosary");
    if(form.otherItems.includes("CLOTHES FOR DRESSING")) parts.push("Clothes for Dressing");
    if(form.otherItems.includes("DENTURES")) parts.push("Dentures");
    if(form.otherItems.includes("OTHER")&&form.otherText) parts.push(`Other: ${form.otherText}`);
    return parts.join(", ")||"Nil";
  }
  function getTransferByOptions(){
    if(isFD){const base=["All Hours","Statewide","MSS"];const fhName=FUNERAL_HOMES.find(f=>f.id===user.funeralHomeId)?.name||"";return fhName?[...base,fhName]:base;}
    return null;
  }

  function validate(){
    const e={};
    if(!form.firstName.trim()) e.firstName="Required";
    if(!form.lastName.trim()) e.lastName="Required";
    if(!form.dob) e.dob="Required";
    if(!form.dod) e.dod="Required";
    if(!form.sex) e.sex="Required";
    if(!form.infectious) e.infectious="Please answer Yes or No";
    if(!form.transferFrom) e.transferFrom="Required";
    if(!form.transferDate) e.transferDate="Required";
    if(!isTransfer&&!isFD&&!form.transferredBy) e.transferredBy="Please choose who transferred (company and person)";
    if(!form.nilVals&&!form.vals) e.valuables="Please select NIL VALS or VALS";
    if(form.vals&&!form.valsText.trim()) e.valuables="Please describe the valuables";
    if(!isFD&&selFH==="OTHER"&&otherFHName.trim().length<4) e.otherFHName="Min 4 characters";
    return e;
  }

  const [dupMatches,setDupMatches]=useState(null);
  // Same person already checked in? Same first + last name (spaces, hyphens, apostrophes ignored) and the same date of birth
  // OR date of death — still in our care, or checked in within the last 30 days. Any funeral director or pick-up place.
  async function findDuplicates(){
    const norm=s=>String(s||"").toLowerCase().replace(/[^a-z]/g,"");
    const since=new Date(Date.now()-30*864e5).toISOString();
    const fhId=isFD?user.funeralHomeId:selFH, from=norm(getTransferDisplay());
    const ors=[form.dob&&"dob.eq."+form.dob,form.dod&&"dod.eq."+form.dod].filter(Boolean);
    if(!ors.length)return [];
    let rows=[];
    try{rows=await sb("cases?select=id,case_ref,first_name,last_name,dob,dod,funeral_home_id,funeral_home_name,transferred_from,checked_in_at,status,checked_out&or=("+encodeURIComponent(ors.join(","))+")&limit=200");}
    catch(err){rows=(cases||[]).filter(x=>(form.dob&&x.dob===form.dob)||(form.dod&&x.dod===form.dod)).map(x=>({id:x.id,case_ref:x.caseRef,first_name:x.firstName,last_name:x.lastName,dob:x.dob,dod:x.dod,funeral_home_id:x.funeralHomeId,funeral_home_name:x.funeralHomeName,transferred_from:x.transferredFrom,checked_in_at:x.checkedInAt,status:x.status,checked_out:x.checkedOut}));}
    return (rows||[]).filter(r=>norm(r.first_name)===norm(form.firstName)&&norm(r.last_name)===norm(form.lastName))
      .filter(r=>(!r.checked_out&&["active","part"].includes(r.status))||String(r.checked_in_at||"")>=since)
      .map(r=>({...r,sameFH:!!fhId&&r.funeral_home_id===fhId,sameFrom:!!from&&norm(r.transferred_from)===from}))
      .filter(r=>r.id!==completing?.id);
  }
  async function submit(force){
    const e=validate();
    if(Object.keys(e).length){setErrors(e);return;}
    if(force!==true){const d=await findDuplicates();if(d.length){setDupMatches(d);return;}}
    else if(dupMatches?.length) logActivity(user,"DUPLICATE CHECK-IN OVERRIDE",`Checked in ${form.firstName} ${form.lastName} again (Admin override) — already ${dupMatches.map(m=>m.case_ref).join(", ")}`,"","");
    setDupMatches(null);
    setSaving(true);
    const caseRef=completing?completing.caseRef:await genCaseRef();
    const fhId=isFD?user.funeralHomeId:selFH;
    const fhName=fhId==="OTHER"?otherFHName:FUNERAL_HOMES.find(f=>f.id===fhId)?.name||"";
    const age=calcAge(form.dob,form.dod);
    const nowIso=new Date().toISOString();
    const partInfo=part?{at:nowIso,by:user?.role==="guest"?(form.transferredBy||"Guest"):user.name,form:{...form,checkInDocs:undefined},docs:(form.checkInDocs||[]).map(d=>({label:d.label,name:d.name})),selFH,otherFHName,checkinRole,noDeathDoc,ciManual}:completing?{at:completing.prep?.partCheckIn?.at,by:completing.prep?.partCheckIn?.by}:null;
    const record={
      id:completing?completing.id:genId(),caseRef,firstName:form.firstName,lastName:form.lastName,
      dob:form.dob,dod:form.dod,sex:form.sex,ageAtDeath:age,
      transferredFrom:getTransferDisplay(),transferredBy:isTransfer||isFD?user.name:form.transferredBy,
      transferPersonName:"",transferDate:form.transferDate,transferTime:form.transferTime,
      valuables:getValuablesDisplay(),paperwork:form.paperwork.join(", "),size:form.size,fridge:form.fridge,weight:form.weight,pacemaker:form.pacemaker||false,
      funeralHomeId:fhId,funeralHomeName:fhName,
      checkedInBy:user.name,checkedInRole:checkinRole,
      checkedInAt:new Date().toISOString(),
      status:part?"part":"active",prepStatus:"not-started",step:1,checkedOut:false,
      prep:{...(completing?.prep||{}),infectious:form.infectious||completing?.prep?.infectious||"",...(form.transferTime?{transferTime:form.transferTime}:{}),...(partInfo?{partCheckIn:partInfo}:{})},billable:completing?.billable||{},otherUsed:completing?.otherUsed||{},statusItems:completing?.statusItems||{},
    };
    try {
      if(completing){await updateCase(record.id,caseToDb(record));}
      else await insertCase(caseToDb(record));
      // Upload check-in documents
      const docs=form.checkInDocs||[];
      for(const doc of docs){
        if(!doc.file) continue;
        try{
          const sf=x=>String(x||"").replace(/[^a-zA-Z0-9]/g,"_");const fhn=FUNERAL_HOMES.find(x=>x.id===fhId)?.name||otherFHName||"FD";const ext=((doc.file.name.match(/\.[a-z0-9]+$/i)||[".pdf"])[0]).toLowerCase();
          const path=`${record.id}/${Date.now()}_${doc.label.replace(/\s+/g,"_")}_${sf(fhn)}_${sf(form.lastName)||"Unknown"}${form.dod?"_"+form.dod.split("-").reverse().join(""):""}${ext}`;
          await fetch(`${SUPABASE_URL}/storage/v1/object/Case-documents/${path}`,{
            method:"POST",
            headers:{"apikey":SUPABASE_KEY,"Authorization":"Bearer "+SUPABASE_KEY,"Content-Type":doc.file.type||"application/octet-stream","x-upsert":"true"},
            body:doc.file
          });
        }catch(e){console.warn("Doc upload error:",e);}
      }
      setSubmitted(record);
      setTimeout(()=>{window.scrollTo({top:0,behavior:"smooth"});window.parent.scrollTo({top:0,behavior:"smooth"});},100);
      if(completing&&onUpdateCase) onUpdateCase(record.id,record); else onComplete(record);
    } catch(err) {
      alert("Error saving case: "+err.message);
    }
    setSaving(false);
  }

  const age=calcAge(form.dob,form.dod);

  if(submitted&&part){
    return (
      <div className="max-w-7xl mx-auto px-4 py-4">
        <button onClick={()=>{onBack();window.scrollTo({top:0,behavior:"smooth"});}} className={`${s.btnGhost} w-full mb-3 py-2`}>← BACK TO HOME</button>
        <div className="bg-amber-50 border-2 border-amber-400 rounded-2xl px-4 py-3 mb-4 flex flex-wrap items-center gap-x-4 gap-y-1">
          <span className="text-2xl">🚐</span>
          <span className="text-lg font-black text-gray-900">Part Checked In — On the way</span>
          <span className="text-lg font-black text-gray-900 tracking-widest">{submitted.caseRef}</span>
          <span className="text-amber-800 font-bold">{submitted.firstName} {submitted.lastName}</span>
          <span className="text-gray-500 text-xs sm:ml-auto">{fmtDTDay(submitted.checkedInAt)}</span>
        </div>
        <DocumentSection caseId={submitted.id} funeralHomeName={submitted.funeralHomeName} lastName={submitted.lastName} dod={submitted.dod}/>
        <button type="button" onClick={()=>{printCaseLabel(submitted,["BODY BAG","PAPERWORK SLEEVE"]);setLabelPrinted(true);}} className={`block w-full mt-5 mb-4 py-6 rounded-2xl border-4 text-lg font-black uppercase tracking-wider ${labelPrinted?"border-green-600 bg-green-50 text-green-800":"border-gray-900 bg-white text-gray-900 hover:bg-gray-50"}`}>{labelPrinted?"✓ Body Bag Tags printed — tap to print again":"🏷️ Print Body Bag Tags"}<span className="block text-xs font-bold normal-case tracking-normal text-gray-500 mt-1">Place 1 on Plastic Sleeve for paperwork, and 1 for body bag.</span></button>
        <div className="bg-gray-900 text-white rounded-2xl p-5 mb-6">
          <div className="font-black uppercase tracking-wide mb-1">⚠ Not checked in yet</div>
          <p className="text-sm text-gray-200">When you arrive at the mortuary, tap <b>✅ CHECK IN</b>, choose <b>{(submitted.lastName||"").toUpperCase()}, {submitted.firstName}</b> then <b>PART CHECK IN</b> at the bottom of the funeral directors, then this name, and finish the check-in. The funeral director is emailed then.</p>
        </div>
      </div>
    );
  }
  if(submitted){
    const fhContacts=submitted.funeralHomeId==="OTHER"?[]:getFHContacts(submitted.funeralHomeId);
    const to=[MORTUARY_EMAIL,...fhContacts].join(",");
    const subj=encodeURIComponent(`T/L ${submitted.firstName} ${submitted.lastName} has been checked into MSS`);
    const body=encodeURIComponent(buildCheckInEmail(submitted));
    return (
      <div className="max-w-7xl mx-auto px-4 py-4">
        <button onClick={()=>{onBack();window.scrollTo({top:0,behavior:"smooth"});}} className={`${s.btnGhost} w-full mb-3 py-2`}>← BACK TO HOME</button>
        <div className="bg-green-50 border border-green-300 rounded-2xl px-4 py-3 mb-4 flex flex-wrap items-center gap-x-4 gap-y-1">
          <span className="inline-flex items-center justify-center w-8 h-8 rounded-full bg-green-100 border border-green-400 flex-none"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#16a34a" strokeWidth="3"><polyline points="20 6 9 17 4 12"/></svg></span>
          <span className="text-lg font-black text-gray-900">Checked In</span>
          <span className="text-lg font-black text-gray-900 tracking-widest">{submitted.caseRef}</span>
          <span className="text-green-700 font-bold">{submitted.firstName} {submitted.lastName}</span>
          <span className="text-gray-500 text-xs sm:ml-auto">{fmtDTDay(submitted.checkedInAt)}</span>
        </div>
        <DocumentSection caseId={submitted.id} funeralHomeName={submitted.funeralHomeName} lastName={submitted.lastName} dod={submitted.dod}/>
        <p className="text-sm font-black uppercase tracking-widest text-gray-700 mt-5 mb-1">To finish, do both:</p>
        <div className="grid gap-3 sm:grid-cols-2 mt-5 mb-2">
        <button type="button" onClick={async()=>{
          let docs=[];try{docs=(await listDocuments(submitted.id)).filter(d=>d.name&&!d.name.endsWith("/"));}catch(e){}
          const nice=n=>n.replace(/^\d+_/,"").replace(/\.[^.]+$/,"").replace(/_/g," ");
          const DOCN={Coroners_BO:"Coroner's BO",MCCD:"MCCD",CRA:"CRA",VOD:"VOD",LE:"Life Extinct (LE)",BO:"BO",OTHER:"Other document",PHOTO:"Photo",Other:"Other document"};
          const docTitle=n=>{const rest=n.replace(/^\d+_/,"");const k=Object.keys(DOCN).find(k=>rest.startsWith(k+"_")||rest===k);return k?DOCN[k]:nice(n);};
          const links=docs.length?`\n\nDOCUMENTS RECEIVED AT CHECK-IN\n`+docs.map(d=>`${docTitle(d.name)} – click here to download:\n\n${encodeURI(getDocumentUrl(submitted.id+"/"+d.name))}`).join("\n\n"):"";
          let text=buildCheckInEmail(submitted);
          text=text.includes(MSS_FOOTER)?text.replace(MSS_FOOTER,links+MSS_FOOTER):text+links;
          if(emailOpened==="sending")return;
          setEmailOpened("sending");
          const att=docs.map(d=>({filename:nice(d.name)+((d.name.match(/\.[a-z0-9]+$/i)||[".pdf"])[0]),path:encodeURI(getDocumentUrl(submitted.id+"/"+d.name))}));
          if(await sendAppEmail(to,decodeURIComponent(subj),text,att)){setEmailOpened("sent");return;}
          window.location.href=`mailto:${to}?subject=${subj}&body=${encodeURIComponent(text)}`;
          setEmailOpened("mailto");
        }} className={`block w-full h-full rounded-2xl text-white font-black uppercase tracking-wider transition shadow-lg ${emailOpened&&emailOpened!=="sending"?"bg-green-600 hover:bg-green-700 py-5 text-lg":"bg-red-600 hover:bg-red-700 py-8 text-xl sm:text-2xl ring-4 ring-red-200 "+(emailOpened?"":"animate-pulse")}`}>
          {emailOpened==="sending"?"1. Sending…":emailOpened==="sent"?"1. ✓ Check-in confirmed — email sent":emailOpened==="mailto"?"1. ✓ Email opened — tap to send again":"1. ✓ Confirm Check In"}
          <span className="block text-xs sm:text-sm font-bold normal-case tracking-normal opacity-90 mt-1">{emailOpened==="sent"?"Sent to the FD & Mortuary — tap to send again":emailOpened==="mailto"?"Make sure you press Send in your mail program":"Required — emails the check-in to the FD & Mortuary"}</span>
        </button>
        <button type="button" onClick={()=>{printCaseLabel(submitted,["BODY BAG","PAPERWORK SLEEVE"]);setLabelPrinted(true);}} className={`block w-full h-full py-5 rounded-2xl border-4 text-lg font-black uppercase tracking-wider ${labelPrinted?"border-green-600 bg-green-50 text-green-800":"border-gray-900 bg-white text-gray-900 hover:bg-gray-50"}`}>{labelPrinted?"2. ✓ Body Bag Tags printed — tap to print again":"2. 🏷️ Print Body Bag Tags"}<span className="block text-xs font-bold normal-case tracking-normal text-gray-500 mt-1">Place 1 on Plastic Sleeve for paperwork, and 1 for body bag.</span></button>
        </div>
        <p className="text-xs text-gray-500 text-center mb-1">Documents above are attached to the email and included as links</p>
        <p className="text-xs text-gray-400 text-center mb-6">To: {to}</p>
      </div>
    );
  }

  const effectiveStep=isFD?3:isTransfer&&step===1?2:step;

  return (
    <div className="max-w-7xl mx-auto px-4 py-4">
      {(()=>{const atStart=isFD||(isTransfer&&effectiveStep===2)||(!isTransfer&&step===1);
        const ciGoBack=()=>{
          if(atStart){if((form.firstName||form.lastName)&&!window.confirm("Leave check-in? Details entered will be lost."))return;onBack();}
          else if(effectiveStep===3)setStep(2);
          else{setStep(1);setSelFH(null);}
          window.scrollTo({top:0,behavior:"smooth"});};
        return <BackBtn onClick={ciGoBack} label={atStart?"Back to Home":effectiveStep===3?"Back to Funeral Directors":"Back"}/>;})()}
      <h2 className="text-xl font-black text-gray-900 mb-2">{completing?"Finish Check In":"Check In"}</h2>
      {completing&&<div className="mb-4 bg-amber-50 border-2 border-amber-400 rounded-2xl px-4 py-3 text-sm"><b>{completing.caseRef} · {(completing.lastName||"").toUpperCase()}, {completing.firstName}</b> — part checked in by {completing.prep?.partCheckIn?.by||completing.checkedInBy}. Check the details, add anything missing, then tap <b>Complete Check-In</b>.</div>}
      {dupMatches&&<div style={{position:"fixed",inset:0,zIndex:2147483000,background:"rgba(0,0,0,0.6)",display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
        <div className="bg-white rounded-2xl max-w-lg w-full p-6 border-4 border-red-500">
          <div className="text-4xl text-center mb-2">⚠️</div>
          <h3 className="text-xl font-black text-red-700 text-center mb-3">This person has already been checked in</h3>
          {dupMatches.map(m=>(
            <div key={m.id} className="bg-red-50 border border-red-200 rounded-xl p-3 mb-3 text-sm">
              <div className="font-black text-gray-900">{m.case_ref} · {(m.last_name||"").toUpperCase()}, {m.first_name}</div>
              <div className="text-gray-700 mt-1">DOB {fmt(m.dob)}{m.dod?" · DOD "+fmt(m.dod):""} · Checked in {fmtDTDay(m.checked_in_at)}{m.checked_out?" · checked out":" · still in our care"}</div>
              <div className="text-gray-700">{m.funeral_home_name}{m.sameFH?" ✓ same funeral director":""}</div>
              <div className="text-gray-700">From: {m.transferred_from||"—"}{m.sameFrom?" ✓ same pick-up location":""}</div>
            </div>))}
          <p className="text-sm text-gray-600 mb-4 text-center">Same name and the same date of birth or date of death. {user?.role==="admin"?"Only check in again if you're sure this is a different person.":"You can't check this person in again. If it really is a different person, call MSS on 02 8814 5500 — Admin can check them in."}</p>
          <div className="flex flex-col sm:flex-row gap-3">
            <button type="button" onClick={()=>setDupMatches(null)} className="flex-1 py-3 rounded-xl bg-gray-900 text-white font-black uppercase">Cancel — don't check in</button>
            {user?.role==="admin"&&<button type="button" onClick={()=>submit(true)} className="flex-1 py-3 rounded-xl border-2 border-red-500 text-red-700 font-black uppercase">Admin: check in anyway</button>}
          </div>
        </div>
      </div>}

      {!isFD&&!isTransfer&&step===1&&(
        <div>
          <p className={s.section}>Who is checking in?</p>
          <div className="grid grid-cols-1 gap-3">
            {[["MSS","MSS Staff"],["TRANSFER TEAM","Transfer Team"],["FUNERAL DIRECTOR","Funeral Director"]].map(([v,l])=>(
              <button key={v} onClick={()=>{setCheckinRole(v);setStep(2);}} className={s.btnLgGhost}>{l}</button>
            ))}
          </div>
        </div>
      )}

      {!isFD&&effectiveStep===2&&(
        <div>
          <p className={s.section}>Select Funeral Director</p>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 mb-4">
            {sortedFH.map(fh=>(
              <button key={fh.id} onClick={()=>{if(selFH===fh.id){setSelFH(null);setStep(2);}else{setSelFH(fh.id);setStep(3);}}}
                className={`py-4 px-3 rounded-xl border-2 text-sm font-bold text-center transition ${selFH===fh.id?"border-gray-900 bg-gray-50":"border-gray-200 hover:border-gray-700"}`}>{fh.name}</button>
            ))}
            {!isTransfer&&<button onClick={()=>setSelFH("OTHER")} className={`py-4 px-3 rounded-xl border-2 text-sm font-bold text-center transition ${selFH==="OTHER"?"border-gray-900 bg-gray-50":"border-gray-200 hover:border-gray-700"}`}>OTHER</button>}
            {canPart&&(()=>{const n=(cases||[]).filter(x=>x.status==="part").length;return <button type="button" disabled={!n} onClick={()=>setShowPart(v=>!v)} className={`col-span-2 sm:col-span-3 py-4 px-3 rounded-xl border-2 text-sm font-black uppercase tracking-wide text-center transition disabled:opacity-40 ${showPart?"border-amber-600 bg-amber-100 text-amber-900":"border-amber-400 bg-amber-50 text-amber-900 hover:border-amber-600"}`}>📲 Part Check In · {n} on the way{n?" — tap to finish":""}</button>;})()}
          </div>
          {showPart&&<PartCheckInList cases={cases} onPick={loadPart} title="Part Checked In — tap a name to finish check-in"/>}
          {selFH==="OTHER"&&(
            <Field label="Funeral Home Name" required>
              <input className={s.inp} value={otherFHName} onChange={e=>setOtherFHName(e.target.value)} placeholder="Enter name (min 4 characters)…"/>
              {errors.otherFHName&&<p className="text-red-500 text-xs mt-1">{errors.otherFHName}</p>}
              <button onClick={()=>{if(otherFHName.trim().length>=4)setStep(3);else setErrors(e=>({...e,otherFHName:"Min 4 characters"}));}} className={`${s.btnDark} w-full mt-2`}>Continue →</button>
            </Field>
          )}
        </div>
      )}

      {(isFD||(effectiveStep===3))&&(
        <div>
          {isFD&&!completing&&!part&&<PartCheckInList cases={(cases||[]).filter(x=>x.funeralHomeId===user.funeralHomeId)} onPick={loadPart} title="Your Part Check Ins — tap a name to finish check-in"/>}
          {(!isTransfer||canPart)&&<div className={`border rounded-xl p-4 mb-5 flex flex-wrap items-center gap-3 ${part?"bg-amber-50 border-amber-400":"bg-gray-50 border-gray-200"}`}>
            <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">Funeral Director:</span>
            <span className="text-base font-bold text-gray-900">{isFD?user.name:selFH==="OTHER"?otherFHName:FUNERAL_HOMES.find(f=>f.id===selFH)?.name}</span>
            {canPart&&!completing&&<button type="button" onClick={()=>setPart(v=>!v)} className={`ml-auto px-5 py-3 rounded-xl border-2 text-sm font-black uppercase tracking-wide transition ${part?"bg-amber-500 border-amber-500 text-white":"bg-white border-amber-400 text-amber-800 hover:border-amber-600"}`}>{part?"✓ Part Check In":"📲 Part Check In"}</button>}
            {part&&<p className="w-full text-sm text-amber-900">On the road: scan the paperwork and fill in the details now. The body is <b>not</b> checked in and the FD is <b>not</b> emailed until you finish at the mortuary.</p>}
          </div>}

          {/* PAPERWORK FIRST */}
          <div className={s.card+" border-2 border-gray-900"}>
            <p className={s.section}>Paperwork Received — start here</p>
            <p className="text-sm text-gray-700 mb-3">{ciManual?<>Tap <b>each document received</b>, then type the details below.</>:<>1. Tap the document you are scanning. &nbsp;2. Tap <b>Scan</b> or <b>Upload</b>. &nbsp;Repeat for each document.</>}</p>
            <div className="flex flex-wrap gap-3 mb-4">
              {[...PAPERWORK_OPTIONS,...(ciManual?[]:["OTHER"])].map(p=>{const locked=!ciManual&&!deathDocDone&&!READ_LABELS.includes(docLabel(p));const done=isScanned(p);const on=ciManual?form.paperwork.includes(p):scanPick===p;return(
                <button key={p} type="button" disabled={locked} title={locked?"Scan the MCCD, BO, VOD or LE first":""} onClick={()=>ciManual?togglePW(p):setScanPick(on?"":p)}
                  className={`px-5 py-3 rounded-xl border-2 text-base font-bold transition disabled:opacity-30 disabled:cursor-not-allowed ${on?"bg-gray-900 text-white border-gray-900":done?"bg-green-50 text-green-800 border-green-500":"bg-white text-gray-500 border-gray-300 hover:border-gray-700"}`}>{locked?"🔒 ":done&&!on?"✓ ":""}{p}</button>);})}
            </div>
            {!ciManual&&<><div className="bg-amber-50 border-2 border-amber-300 rounded-xl px-4 py-3 text-sm text-amber-900 font-bold mb-4">✨ By scanning or uploading the MCCD, BO, VOD or LE, the app will automatically fill in the deceased's details and where they came from. Please check every detail is correct before submitting.</div>
            <button type="button" disabled={!scanLabel} onClick={()=>setScanOpen(true)} className="w-full py-4 rounded-xl bg-gray-900 hover:bg-gray-700 text-white text-base font-black uppercase tracking-wide disabled:opacity-30 disabled:cursor-not-allowed">📷 Scan {scanLabel?(DOC_NAME[scanLabel]||scanLabel):"Paperwork"}</button>
            <label className={`mt-2 w-full py-4 rounded-xl border-2 border-gray-900 bg-white text-gray-900 text-base font-black uppercase tracking-wide flex items-center justify-center gap-2 ${scanLabel?"cursor-pointer hover:bg-gray-50":"opacity-30 cursor-not-allowed"}`}>📤 Upload {scanLabel?(DOC_NAME[scanLabel]||scanLabel):"from phone or computer"}<input type="file" multiple accept="image/*,application/pdf,.pdf" disabled={!scanLabel} className="hidden" onChange={e=>{const fl=Array.from(e.target.files||[]);e.target.value="";ciUpload(fl);}}/></label>
            {!scanLabel&&<p className="text-xs text-gray-500 mt-2 text-center">{deathDocDone?"Tap the next document above to scan or upload it":"Tap MCCD, BO, VOD or LE above, then Scan or Upload"}</p>}</>}
            {!ciManual
              ?<button type="button" onClick={()=>{setCiManual(true);setScanPick("");setNoDeathDoc(true);setTimeout(()=>{const el=document.querySelector('input[placeholder="First name"]');if(el){el.scrollIntoView({behavior:"smooth",block:"center"});el.focus();}},80);}} className="w-full mt-3 py-4 rounded-xl border-2 border-gray-900 bg-white text-gray-900 text-base font-black uppercase tracking-wide hover:bg-gray-50">✍️ Enter Manually</button>
              :<p className="text-sm text-gray-700 mt-1 text-center font-bold">✍️ Manual entry — type the details below. <button type="button" onClick={()=>{setCiManual(false);setNoDeathDoc(false);}} className="underline">Scan instead</button></p>}
            {scanOpen&&<DocumentScanner labels={["MCCD","Coroners BO","VOD","LE","CRA","OTHER"]} defaultLabel={scanLabel||undefined} readLabels={READ_LABELS} onRead={readDocument} lockedLabels={deathDocDone?[]:["CRA","OTHER"]} fileBase={{fh:FUNERAL_HOMES.find(f=>f.id===(isFD?user.funeralHomeId:selFH))?.name,lastName:form.lastName,dod:form.dod}} onClose={()=>setScanOpen(false)}
              prefixLabel={false} onSave={(file,lbl)=>{setScanPick("");setForm(f=>{const pw=lbl==="Coroners BO"?"BO":lbl;return{...f,checkInDocs:[...(f.checkInDocs||[]),(lastScanRef.current={label:lbl,name:file.name,file})],paperwork:PAPERWORK_OPTIONS.includes(pw)&&!f.paperwork.includes(pw)?[...f.paperwork,pw]:f.paperwork};});}}/>}
            {(form.checkInDocs||[]).length>0&&<div className="mt-3">
              <p className="text-xs text-green-700 font-bold mb-2">✓ Documents added{ocr.status==="done"?" — details filled in, please check them":""}</p>
              {(form.checkInDocs||[]).map((doc,i)=>(
                <div key={i} className="flex items-center gap-2 mb-1.5 bg-green-50 border border-green-200 rounded-xl px-3 py-2">
                  <span className="text-xs font-black text-green-800 uppercase">{DOC_NAME[doc.label]||doc.label}</span>
                  <span className="text-xs text-gray-500 flex-1 truncate">{doc.name}</span>
                  {doc.existing?<span className="text-[10px] font-black text-green-700 uppercase">Saved</span>:<button type="button" title="Remove" onClick={()=>setF("checkInDocs",(form.checkInDocs||[]).filter((_,j)=>j!==i))} className="text-red-400 font-black text-xs hover:text-red-600 px-1">✕</button>}
                </div>))}
            </div>}
            {!ciManual&&!deathDocDone&&<p className="text-xs text-gray-500 mt-3 text-center">No MCCD, BO, VOD or LE with this body? <button type="button" onClick={()=>setNoDeathDoc(true)} className="underline font-bold text-gray-700">No death paperwork with this body</button></p>}
          </div>

          {ocr.status&&ocr.status!=="done"&&<div id="ocr-banner" className={`rounded-xl border-2 px-4 py-3 mb-4 text-sm font-bold flex items-start justify-between gap-3 ${ocr.status==="reading"?"bg-blue-50 border-blue-300 text-blue-800":ocr.status==="confirm"?"bg-red-50 border-red-400 text-red-900":ocr.status==="done"?"bg-amber-50 border-amber-400 text-amber-900":"bg-gray-50 border-gray-300 text-gray-700"}`}>
            {ocr.status==="confirm"
              ?<div className="flex-1">
                <p>⚠️ That looks like a {DOC_NAME[ocr.detected]||ocr.detected}, not a {DOC_NAME[ocr.label]||ocr.label}. Please confirm.</p>
                <div className="flex flex-wrap gap-2 mt-2">
                  <button type="button" onClick={()=>applyRead(ocr.fields,ocr.label)} className="px-3 py-2 rounded-lg bg-gray-900 text-white text-xs font-black uppercase">It is a {DOC_NAME[ocr.label]||ocr.label}</button>
                  <button type="button" onClick={()=>{const nl=ocr.detected==="Other"?"OTHER":ocr.detected;if(ocr.doc)relabelDoc(ocr.doc,nl);if(READ_LABELS.includes(nl))applyRead(ocr.fields,nl);else setOcr({status:"none",msg:`Saved as ${DOC_NAME[nl]||nl}. Now scan the MCCD, Coroner's BO, LE or VOD.`});}} className="px-3 py-2 rounded-lg bg-white border-2 border-gray-900 text-gray-900 text-xs font-black uppercase">Change to {DOC_NAME[ocr.detected]||ocr.detected}</button>
                </div>
              </div>
              :<span>{ocr.status==="reading"?"⏳ ":ocr.status==="done"?"✨ ":"ℹ️ "}{ocr.msg}</span>}
            {ocr.status!=="reading"&&ocr.status!=="confirm"&&<button type="button" onClick={()=>setOcr({status:"",msg:""})} className="text-xs font-black uppercase opacity-60 hover:opacity-100">✕</button>}
          </div>}
          <div className={s.card}>
            <p className={s.section}>Deceased Details</p>
            <div className="grid grid-cols-2 gap-3">
              <Field label="First Name" required><input className={s.inp} value={form.firstName} onChange={e=>setF("firstName",e.target.value)} placeholder="First name"/>{errors.firstName&&<p className="text-red-500 text-xs mt-1">{errors.firstName}</p>}</Field>
              <Field label="Last Name" required><input className={s.inp} value={form.lastName} onChange={e=>setF("lastName",e.target.value)} placeholder="Last name"/>{errors.lastName&&<p className="text-red-500 text-xs mt-1">{errors.lastName}</p>}</Field>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <Field label="Date of Birth" required><DOBPicker value={form.dob} onChange={v=>setF("dob",v)} maxDate={today()} minDate={minDOB()}/>{errors.dob&&<p className="text-red-500 text-xs mt-1">{errors.dob}</p>}</Field>
              <Field label="Date of Death" required><DOBPicker value={form.dod} onChange={v=>setF("dod",v)} maxDate={today()}/>{errors.dod&&<p className="text-red-500 text-xs mt-1">{errors.dod}</p>}</Field>
            </div>
            {form.dob&&form.dod&&age!==null&&<div className="bg-blue-50 border border-blue-200 rounded-xl px-4 py-2 mb-3 text-sm"><span className="text-blue-600 font-bold">Age at Death: {age} years</span></div>}
            <Field label="Sex" required>
              <div className="flex gap-6 mt-1">
                {["Male","Female","Other"].map(sx=>(
                  <label key={sx} className="flex items-center gap-2 cursor-pointer">
                    <input type="radio" name="sex" checked={form.sex===sx} onChange={()=>setF("sex",sx)} className="w-5 h-5 accent-gray-900"/>
                    <span className="text-base font-medium text-gray-800">{sx}</span>
                  </label>
                ))}
              </div>
              {errors.sex&&<p className="text-red-500 text-xs mt-1">{errors.sex}</p>}
            </Field>
          </div>

          <div className={s.card}>
            <p className={s.section}>Transfer Details</p>
            <Field label="Transferred From" required>
              <TransferFromPicker value={form.transferFrom} subValue={form.transferFromSub} onChangeType={v=>{setF("transferFrom",v);setF("transferFromSub",v==="Coroners"?"Sydney":"");}} onChangeSub={v=>setF("transferFromSub",v)}/>
              {errors.transferFrom&&<p className="text-red-500 text-xs mt-1">{errors.transferFrom}</p>}
            </Field>
            {!isTransfer&&!isFD&&(
              <Field label="Transferred By" required>
                <TransferByPicker value={form.transferredBy} onChange={v=>setF("transferredBy",v)}/>
                {errors.transferredBy&&<p className="text-red-500 text-xs mt-1">{errors.transferredBy}</p>}
              </Field>
            )}
            <Field label="Transfer Date" required><input type="date" className={s.inp} value={form.transferDate} onChange={e=>setF("transferDate",e.target.value)} max={today()}/>{form.transferDate&&<p className="text-xs font-black text-gray-700 mt-1">{fmtDayLong(form.transferDate)}</p>}</Field>
            <Field label="Transfer Time"><input type="time" className={s.inp} value={form.transferTime||""} onChange={e=>setF("transferTime",e.target.value)}/></Field>
            <Field label="Valuables / Items" required>
              <ValuablesPicker
                nilVals={form.nilVals} vals={form.vals} valsText={form.valsText}
                otherItems={form.otherItems} otherText={form.otherText}
                onSetNilVals={v=>setF("nilVals",v)}
                onSetVals={v=>setF("vals",v)}
                onSetValsText={v=>setF("valsText",v)}
                onToggleOther={toggleOther}
                onSetOtherText={v=>setF("otherText",v)}
                error={errors.valuables}/>
            </Field>
          </div>

          <div className={s.card}>
            <p className={s.section}>PHYSICAL DETAILS</p>
            <Field label="SIZE">
              <div className="flex flex-wrap gap-2">
                {["STD","OS1","OS2","OS3"].map(o=>(
                  <button key={o} type="button" onClick={()=>setF("size",form.size===o?"":o)}
                    className={`flex-1 py-3 rounded-xl border-2 font-black text-sm uppercase transition ${form.size===o?"bg-gray-900 text-white border-gray-900":"border-gray-300 text-gray-600 hover:border-gray-700"}`}>
                    {o}
                  </button>
                ))}
              </div>
            </Field>
            <Field label="FRIDGE">
              <div className="flex flex-wrap gap-2">
                {["OLD","NEW"].map(o=>(
                  <button key={o} type="button" onClick={()=>setF("fridge",form.fridge===o?"":o)}
                    className={`flex-1 py-3 rounded-xl border-2 font-black text-sm uppercase transition ${form.fridge===o?"bg-gray-900 text-white border-gray-900":"border-gray-300 text-gray-600 hover:border-gray-700"}`}>
                    {o}
                  </button>
                ))}
              </div>
            </Field>
            <Field label="WEIGHT (IF KNOWN)">
              <input className={s.inp} placeholder="e.g. 85kg" value={form.weight} onChange={e=>setF("weight",e.target.value)}/>
            <Field label="Does this deceased have an infectious disease? *"><div className="grid grid-cols-2 gap-2">{["Yes","No"].map(v=><button key={v} type="button" onClick={()=>setF("infectious",v)} className={"py-3 rounded-xl border-2 font-black text-sm uppercase transition "+(form.infectious===v?(v==="Yes"?"bg-red-600 text-white border-red-600":"bg-green-600 text-white border-green-600"):"border-gray-200 text-gray-600 hover:border-gray-400")}>{v==="Yes"?"☣ YES — INFECTIOUS":"NO"}</button>)}</div>{errors.infectious&&<p className="text-red-500 text-xs mt-1">{errors.infectious}</p>}</Field>
            <Field label="Pacemaker Fitted"><button type="button" onClick={()=>setF("pacemaker",!form.pacemaker)} className={"w-full py-3 rounded-xl border-2 font-black text-sm uppercase transition "+(form.pacemaker?"bg-red-600 text-white border-red-600":"border-gray-200 text-gray-600 hover:border-red-400")}>⚠️ {form.pacemaker?"YES — PACEMAKER FITTED":"No Pacemaker"}</button></Field>
            </Field>
          </div>

          <button onClick={submit} disabled={saving} className={`${s.btnDark} w-full text-lg py-4 disabled:opacity-40`}>{saving?"Saving…":part?"Save Part Check-In →":completing?"Complete Check-In →":"Submit Check-In →"}</button>
        </div>
      )}
    </div>
  );
}


// ─── PACEMAKER CERTIFICATE VIEW ──────────────────────────────────────────────
function PacemakerCertificateView({cert, onClose}){
  function fmt2(d){if(!d)return "—";try{const x=new Date(d+"T12:00:00");return x.toLocaleDateString("en-AU",{day:"2-digit",month:"long",year:"numeric"});}catch{return d;}}
  function printCert(){
    const pw=window.open("","_blank");
    pw.document.write(`<!DOCTYPE html><html><head><title>Pacemaker Certificate</title><style>
      *{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,sans-serif;padding:40px;color:#111;}
      .header{border-bottom:3px solid #111;padding-bottom:16px;margin-bottom:24px;display:flex;align-items:center;justify-content:space-between;}
      .logo-wrap{display:flex;align-items:center;gap:16px;}
      .logo-div{width:1px;height:52px;background:#111;}
      .logo-main{font-family:Georgia,serif;font-size:18px;font-weight:400;color:#111;letter-spacing:3px;text-transform:uppercase;}
      .logo-sub{font-family:Georgia,serif;font-size:11px;font-weight:300;color:#555;letter-spacing:7px;text-transform:uppercase;margin-top:5px;}
      .contact{text-align:right;font-size:11px;color:#666;line-height:1.8;}
      .title{text-align:center;font-size:18px;font-weight:900;letter-spacing:2px;text-transform:uppercase;margin-bottom:24px;border:2px solid #111;padding:10px;}
      .grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px;}
      .fl{font-size:9px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#666;margin-bottom:3px;}
      .fv{font-size:14px;font-weight:700;border-bottom:1px solid #999;padding-bottom:3px;min-height:24px;}
      .stmt{background:#f5f5f5;border:1px solid #ccc;padding:14px;margin:16px 0;font-size:11px;line-height:1.6;}
      .sigs{margin-top:32px;display:grid;grid-template-columns:1fr 1fr;gap:32px;}
      .sigbox{border-top:2px solid #111;padding-top:6px;}
      .siglabel{font-size:9px;letter-spacing:2px;text-transform:uppercase;color:#666;}
      .sigimg{max-height:70px;margin-bottom:6px;}
      .footer{margin-top:32px;border-top:1px solid #ccc;padding-top:10px;font-size:9px;color:#999;text-align:center;}
    </style></head><body>
    <div class="header">
      <div class="logo-wrap">
        <svg width="44" height="55" viewBox="0 0 64 80" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path d="M32 75 Q30 60 32 45" stroke="#111" stroke-width="1.4" fill="none" stroke-linecap="round"/>
          <path d="M32 62 Q20 55 16 46 Q25 52 32 58" stroke="#111" stroke-width="1" fill="none"/>
          <path d="M32 57 Q44 51 48 42 Q39 49 32 55" stroke="#111" stroke-width="1" fill="none"/>
          <path d="M32 44 Q16 34 12 16 Q20 30 28 40 Q30 42 32 44" stroke="#111" stroke-width="1.2" fill="none"/>
          <path d="M32 44 Q48 34 52 16 Q44 30 36 40 Q34 42 32 44" stroke="#111" stroke-width="1.2" fill="none"/>
          <path d="M32 44 Q18 30 20 10 Q26 28 30 41 Q31 43 32 44" stroke="#111" stroke-width="1" fill="none"/>
          <path d="M32 44 Q46 30 44 10 Q38 28 34 41 Q33 43 32 44" stroke="#111" stroke-width="1" fill="none"/>
          <path d="M32 44 Q25 26 32 6 Q39 26 32 44" stroke="#111" stroke-width="1" fill="none"/>
          <line x1="32" y1="44" x2="25" y2="31" stroke="#111" stroke-width="0.8"/>
          <line x1="32" y1="44" x2="32" y2="29" stroke="#111" stroke-width="0.8"/>
          <line x1="32" y1="44" x2="39" y2="31" stroke="#111" stroke-width="0.8"/>
          <circle cx="25" cy="30" r="1.8" fill="#111"/>
          <circle cx="32" cy="28" r="1.8" fill="#111"/>
          <circle cx="39" cy="30" r="1.8" fill="#111"/>
        </svg>
        <div class="logo-div"></div>
        <div><div class="logo-main">Mortuary Support</div><div class="logo-sub">Lum&#x113;n</div></div>
      </div>
      <div class="contact">Mortuary Support Services NSW<br/>Ph: 02 8814 5500<br/>info@mortuarysupport.com.au</div>
    </div>
    <div class="title">PACEMAKER REMOVAL CERTIFICATE</div>
    <div class="grid">
      <div><div class="fl">Deceased Full Name</div><div class="fv">${cert.first_name} ${cert.last_name}</div></div>
      <div><div class="fl">Case Reference</div><div class="fv">${cert.case_ref}</div></div>
      <div><div class="fl">Date of Birth</div><div class="fv">${fmt2(cert.dob)}</div></div>
      <div><div class="fl">Date of Death</div><div class="fv">${fmt2(cert.dod)}</div></div>
      <div><div class="fl">Funeral Director</div><div class="fv">${cert.funeral_home_name||"—"}</div></div>
      <div><div class="fl">Date of Removal</div><div class="fv">${fmt2(cert.removal_date)}</div></div>
    </div>
    <div class="stmt"><strong>DECLARATION:</strong><br/><br/>I hereby certify that I have examined the above-named deceased and have successfully removed the pacemaker/implantable cardiac device prior to cremation/preparation. The device has been safely disposed of in accordance with relevant regulations and guidelines.<br/><br/>This removal was carried out at MSS Mortuary Support Services, Baulkham Hills NSW.</div>
    <div><div class="fl">Embalmer / Technician Name</div><div class="fv">${cert.embalmer_name}</div></div>
    <div class="sigs">
      <div class="sigbox">${cert.signature_data?`<img src="${cert.signature_data}" class="sigimg" alt="Signature"/>`:"<div style='height:70px'></div>"}<div class="siglabel">Signature of Embalmer / Technician</div></div>
      <div class="sigbox"><div style="height:70px"></div><div class="siglabel">Authorised by MSS</div></div>
    </div>
    <div class="footer">MSS Mortuary Support Services · Mortuary Support | Lum&#x113;n NSW · Ph: 02 8814 5500 · info@mortuarysupport.com.au<br/>This certificate is issued for the purposes of cremation/preparation documentation.</div>
    </body></html>`);
    pw.document.close();pw.focus();setTimeout(()=>pw.print(),400);
  }
  return(
    <div style={{position:"fixed",top:0,left:0,width:"100vw",height:"100vh",zIndex:2147483647,background:"rgba(0,0,0,0.6)",display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"40px 16px 16px"}}>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md max-h-[90vh] overflow-y-auto">
        <div className="bg-amber-600 text-white rounded-t-2xl p-5 flex items-center justify-between">
          <div>
            <p className="text-xs font-black uppercase tracking-widest text-amber-200">Case {cert.case_ref}</p>
            <h2 className="text-lg font-black uppercase">Pacemaker Certificate</h2>
          </div>
          <button onClick={onClose} className="text-amber-200 hover:text-white font-black text-xl">✕</button>
        </div>
        <div className="p-6 space-y-3">
          <div className="grid grid-cols-2 gap-3 bg-gray-50 rounded-xl p-4 text-sm">
            <div><span className="text-gray-500 font-bold uppercase text-xs">Name: </span><span className="font-black">{cert.first_name} {cert.last_name}</span></div>
            <div><span className="text-gray-500 font-bold uppercase text-xs">Ref: </span><span className="font-black">{cert.case_ref}</span></div>
            <div><span className="text-gray-500 font-bold uppercase text-xs">Removed: </span><span className="font-black">{fmt2(cert.removal_date)}</span></div>
            <div><span className="text-gray-500 font-bold uppercase text-xs">By: </span><span className="font-black">{cert.embalmer_name}</span></div>
            <div className="col-span-2"><span className="text-gray-500 font-bold uppercase text-xs">FD: </span><span className="font-black">{cert.funeral_home_name}</span></div>
          </div>
          {cert.signature_data&&(
            <div className="bg-gray-50 rounded-xl p-4">
              <p className="text-xs font-black uppercase text-gray-400 mb-2">Signature</p>
              <img src={cert.signature_data} alt="Signature" className="max-h-20 border border-gray-200 rounded-lg bg-white p-2"/>
            </div>
          )}
          <button onClick={printCert} className="w-full py-3 rounded-xl bg-gray-900 text-white font-black uppercase text-sm hover:bg-gray-700 transition">
            📄 PRINT / SAVE AS PDF
          </button>
        </div>
      </div>
    </div>
  );
}

