// ─── STAFF/ADMIN: resend the check-in notification (same email as at check-in, with the documents) ───
function ResendCheckInButton({c,user}){
  const [st,setSt]=useState("");
  if(!["admin","mss"].includes(user?.role))return null;
  async function go(){
    if(st==="sending")return;setSt("sending");
    let docs=[];try{docs=(await listDocuments(c.id)).filter(d=>d.name&&!d.name.endsWith("/"));}catch(e){}
    const nice=n=>n.replace(/^\d+_/,"").replace(/\.[^.]+$/,"").replace(/_/g," ");
    const DOCN={Coroners_BO:"Coroner's BO",MCCD:"MCCD",CRA:"CRA",VOD:"VOD",LE:"Life Extinct (LE)",BO:"BO",OTHER:"Other document",PHOTO:"Photo",Other:"Other document"};
    const docTitle=n=>{const rest=n.replace(/^\d+_/,"");const k=Object.keys(DOCN).find(k=>rest.startsWith(k+"_")||rest===k);return k?DOCN[k]:nice(n);};
    const links=docs.length?`\n\nDOCUMENTS RECEIVED AT CHECK-IN\n`+docs.map(d=>`${docTitle(d.name)} – click here to download:\n\n${encodeURI(getDocumentUrl(c.id+"/"+d.name))}`).join("\n\n"):"";
    let text=buildCheckInEmail(c);text=text.includes(MSS_FOOTER)?text.replace(MSS_FOOTER,links+MSS_FOOTER):text+links;
    const fhContacts=c.funeralHomeId==="OTHER"?[]:getFHContacts(c.funeralHomeId);
    const to=[MORTUARY_EMAIL,...fhContacts].join(",");
    const att=docs.map(d=>({filename:nice(d.name)+((d.name.match(/\.[a-z0-9]+$/i)||[".pdf"])[0]),path:encodeURI(getDocumentUrl(c.id+"/"+d.name))}));
    if(await sendAppEmail(to,`T/L ${c.firstName} ${c.lastName} has been checked into MSS`,text,att)){
      logActivity(user,"CHECK-IN EMAIL RESENT",`Check-in notification resent for ${c.firstName} ${c.lastName} to ${to}`,c.caseRef,c.id);setSt("sent");}
    else setSt("failed");
  }
  return(<div>
    <button type="button" onClick={go} disabled={st==="sending"} className="w-full py-3 rounded-xl border-2 border-gray-900 text-gray-900 font-black text-sm uppercase hover:bg-gray-100 disabled:opacity-60">{st==="sending"?"Sending…":"📧 Resend check-in notification"}</button>
    {st==="sent"&&<p className="text-xs font-bold text-green-700 mt-1 text-center">✓ Sent to the funeral director and the mortuary</p>}
    {st==="failed"&&<p className="text-xs font-bold text-red-600 mt-1 text-center">Couldn't send — check the funeral director's email, or try again.</p>}
  </div>);
}

// ─── ADMIN: undo a check out made by mistake (the deceased goes back into our care) ───
function AdminUndoCheckout({c,user,onUpdateCase,small,onDone}){
  const [open,setOpen]=useState(false),[busy,setBusy]=useState(false),[err,setErr]=useState("");
  if(user?.role!=="admin"||!c.checkedOut)return null;
  const locked=c.status==="locked", sentAcc=c.prep?.jobSheetSentAt;
  async function go(){
    setBusy(true);setErr("");
    try{
      const prev=c.checkout||{};
      // Also clears "sent to accounts", so it can be sent again when they're checked out for real
      const np={...(c.prep||{})};delete np.jobSheetSentAt;delete np.jobSheetSentBy;
      await updateCase(c.id,{checked_out:false,checkout_data:null,status:"active",prep:np});
      onUpdateCase(c.id,{checkedOut:false,checkout:null,status:"active",prep:np});
      logActivity(user,"CHECK OUT UNDONE",`${c.caseRef} ${(c.lastName||"").toUpperCase()}, ${c.firstName} checked back in by Admin (was checked out ${prev.checkedOutAt?fmtDTDay(prev.checkedOutAt):"—"}${prev.signedName?" to "+prev.signedName:""}${sentAcc?"; job sheet had been sent to accounts "+fmtDTDay(sentAcc):""}${locked?"; case was locked":""})`,c.caseRef,c.id);
      setOpen(false);onDone&&onDone();
    }catch(e){setErr("Couldn't undo: "+(e.message||e));}
    setBusy(false);
  }
  return(<>
    <button type="button" onClick={e=>{e.stopPropagation();setErr("");setOpen(true);}} className={small?"text-xs bg-orange-500 text-white rounded-lg px-3 py-1.5 hover:bg-orange-600 transition font-black uppercase":"w-full py-3 rounded-xl border-2 border-orange-400 text-orange-700 font-black text-sm uppercase hover:bg-orange-50"}>↩ Undo check out{small?"":" (Admin)"}</button>
    {open&&<div onClick={e=>e.stopPropagation()} style={{position:"fixed",inset:0,zIndex:2147483000,background:"rgba(0,0,0,0.6)",display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div className="bg-white rounded-2xl max-w-md w-full p-6 border-4 border-orange-400 text-left">
        <div className="text-3xl text-center mb-2">↩</div>
        <h3 className="text-xl font-black text-orange-700 text-center mb-3">Check {c.firstName} back in?</h3>
        <div className="bg-orange-50 border border-orange-200 rounded-xl p-3 mb-3 text-sm">
          <div className="font-black text-gray-900">{c.caseRef} · {(c.lastName||"").toUpperCase()}, {c.firstName}</div>
          <div className="text-gray-700 mt-1">{c.funeralHomeName} · Checked out {c.checkout?.checkedOutAt?fmtDTDay(c.checkout.checkedOutAt):"—"}{c.checkout?.signedName?" · collected by "+c.checkout.signedName:""}</div>
        </div>
        <p className="text-sm text-gray-600 mb-3">Use this if the check out was a mistake. The case goes back to <b>in our care</b> and the check-out details are cleared. It's recorded in the Activity Log. No email is sent.</p>
        {sentAcc&&<p className="text-sm font-bold text-amber-800 bg-amber-50 border border-amber-200 rounded-xl p-3 mb-3">The Job Sheet was already sent to accounts on {fmtDTDay(sentAcc)}. Let accounts know to hold the invoice. It can be sent again after the real check out.</p>}
        {locked&&<p className="text-sm font-bold text-amber-800 bg-amber-50 border border-amber-200 rounded-xl p-3 mb-3">This case is locked. Checking back in unlocks it.</p>}
        {err&&<p className="text-sm font-bold text-red-600 mb-3">{err}</p>}
        <div className="flex flex-col sm:flex-row gap-3">
          <button type="button" onClick={()=>setOpen(false)} className="flex-1 py-3 rounded-xl bg-gray-900 text-white font-black uppercase">Cancel</button>
          {<button type="button" disabled={busy} onClick={go} className="flex-1 py-3 rounded-xl bg-orange-500 hover:bg-orange-600 disabled:opacity-60 text-white font-black uppercase">{busy?"Saving…":"Check back in"}</button>}
        </div>
      </div>
    </div>}
  </>);
}

// ─── ADMIN: DELETE A CASE (e.g. a duplicate check-in) ─────────────────────────
function AdminDeleteCase({c,user,onDeleted,small}){
  const [open,setOpen]=useState(false),[busy,setBusy]=useState(false),[err,setErr]=useState("");
  if(user?.role!=="admin")return null;
  async function del(){
    setBusy(true);setErr("");
    try{
      // A 2nd Note linked to this case goes back to "waiting for a case" rather than being lost
      await sb(`second_notes?case_id=eq.${c.id}`,{method:"PATCH",body:JSON.stringify({case_id:null,case_ref:null,status:"awaiting"})}).catch(()=>{});
      await sb(`cases?id=eq.${c.id}`,{method:"DELETE"});
      logActivity(user,"CASE DELETED",`${c.caseRef} ${(c.lastName||"").toUpperCase()}, ${c.firstName} (${c.funeralHomeName||""}) deleted by Admin`,c.caseRef,c.id);
      setOpen(false);onDeleted&&onDeleted(c);
    }catch(e){setErr("Couldn't delete: "+(e.message||e));}
    setBusy(false);
  }
  return(<>
    <button type="button" onClick={e=>{e.stopPropagation();setOpen(true);}} className={small?"shrink-0 px-3 py-3 rounded-xl border-2 border-red-300 text-red-600 font-black text-sm uppercase hover:bg-red-50":"w-full py-3 rounded-xl border-2 border-red-300 text-red-600 font-black text-sm uppercase hover:bg-red-50"} title="Delete case (Admin)">🗑{small?"":" Delete case (Admin)"}</button>
    {open&&<div onClick={e=>e.stopPropagation()} style={{position:"fixed",inset:0,zIndex:2147483000,background:"rgba(0,0,0,0.6)",display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div className="bg-white rounded-2xl max-w-md w-full p-6 border-4 border-red-500 text-left">
        <div className="text-3xl text-center mb-2">🗑</div>
        <h3 className="text-xl font-black text-red-700 text-center mb-3">Delete this case?</h3>
        <div className="bg-red-50 border border-red-200 rounded-xl p-3 mb-3 text-sm">
          <div className="font-black text-gray-900">{c.caseRef} · {(c.lastName||"").toUpperCase()}, {c.firstName}</div>
          <div className="text-gray-700 mt-1">{c.funeralHomeName}{c.checkedInAt?" · Checked in "+fmtDTDay(c.checkedInAt):""}</div>
        </div>
        <p className="text-sm text-gray-600 mb-4">This permanently removes the case from Lumière. Use it for duplicates or mistakes only. It's recorded in the Activity Log.</p>
        {err&&<p className="text-sm font-bold text-red-600 mb-3">{err}</p>}
        <div className="flex flex-col sm:flex-row gap-3">
          <button type="button" onClick={()=>setOpen(false)} className="flex-1 py-3 rounded-xl bg-gray-900 text-white font-black uppercase">Cancel</button>
          <button type="button" disabled={busy} onClick={del} className="flex-1 py-3 rounded-xl bg-red-600 hover:bg-red-700 disabled:opacity-60 text-white font-black uppercase">{busy?"Deleting…":`Delete ${c.caseRef}`}</button>
        </div>
      </div>
    </div>}
  </>);
}

function MortuaryFlow({user,cases,onUpdateCase,onBack}) {
  const [initCase]=useState(()=>{const x=_openCaseId&&cases.find(k=>k.id===_openCaseId);_openCaseId=null;return x||null;});
  const [selFH,setSelFH]=useState(()=>initCase?(FUNERAL_HOMES.find(f=>f.id===initCase.funeralHomeId)||{id:initCase.funeralHomeId,name:initCase.funeralHomeName}):null);
  const [selCase,setSelCase]=useState(initCase);
  const [showPacemakerCert,setShowPacemakerCert]=useState(false);
  const [docReload,setDocReload]=useState(0);
  useEffect(()=>{window.scrollTo({top:0,behavior:"smooth"});},[selFH?.id,selCase?.id]);

  const byFH={};
  cases.filter(c=>c.status==="active").forEach(c=>{if(!byFH[c.funeralHomeId])byFH[c.funeralHomeId]=[];byFH[c.funeralHomeId].push(c);});
  const toAccounts=cases.filter(c=>c.checkedOut&&c.checkout?.checkedOutAt&&!c.prep?.jobSheetSentAt&&!c.invoicedAt).sort((a,b)=>new Date(a.checkout.checkedOutAt)-new Date(b.checkout.checkedOutAt));
  // Tick several (or all) checked-out cases and send them to accounts in one go
  const [accSel,setAccSel]=useState({}),[accBusy,setAccBusy]=useState(""),[accMsg,setAccMsg]=useState("");
  const accTicked=toAccounts.filter(x=>accSel[x.id]),allTicked=toAccounts.length>0&&accTicked.length===toAccounts.length;
  async function sendTicked(){
    if(!accTicked.length||accBusy)return;setAccMsg("");let ok=0;const bad=[];
    for(let i=0;i<accTicked.length;i++){const x=accTicked[i];setAccBusy(`Sending ${i+1} of ${accTicked.length}…`);
      try{const prep=x.prep||{};const r=await sendJobSheet(x,prep,x.billable||{},x.checkout?.checkedOutBy||"");
        if(r.status==="sent"){const np={...prep,jobSheetSentAt:new Date().toISOString(),jobSheetSentBy:user?.name||""};await updateCase(x.id,{prep:np});onUpdateCase(x.id,{prep:np});ok++;}
        else bad.push(x.caseRef);}catch(e){bad.push(x.caseRef);}}
    setAccBusy("");setAccSel({});
    if(ok)logActivity(user,"SENT TO ACCOUNTS",`${ok} job sheet${ok>1?"s":""} sent to accounts together`,"","");
    setAccMsg(`✓ ${ok} sent to accounts${bad.length?` · not sent: ${bad.join(", ")} — try those one at a time`:""}`);
  }

  function describeChanges(updates,existingCase){
    const labels={
      prep:"Preparation details",last_name:"Last name",first_name:"First name",lastName:"Last name",firstName:"First name",
      dob:"Date of birth",dod:"Date of death",sex:"Sex",paperwork:"Paperwork",
      funeral_home_name:"Funeral director",billable:"Services & items",
      statusItems:"Checklist",
    };
    // High-level change grouping
    const PREP_GROUPS={
      viewing:["viewing","viewingSlot","viewingDate","viewingLocation","viewingHost","viewingDuration"],
      dates:["collectionDate","collectionTime","funeralDate","funeralTime","sameDates"],
      disposition:["disposition"],
      coffin:["coffinType","coffinSize","coffinColour","coffinName","coffinHandles","otherInstructions"],
      preparation:["prepOptions"],
      comments:["comments"],
      valuables:["mortuaryValuables","mortuaryValuablesText"],
    };
    const GROUP_LABELS={viewing:"Viewing updated",dates:"Dates updated",disposition:"Disposition updated",coffin:"Coffin details updated",preparation:"Preparation type updated",comments:"Comments updated",valuables:"Valuables updated"};
    function fmt(d){if(!d)return"—";if(d.match&&d.match(/^\d{4}-\d{2}-\d{2}$/)){const[y,m,dd]=d.split("-");return dd+"/"+m+"/"+y;}return String(d);}
    const changes=[];
    Object.keys(updates).forEach(k=>{
      if(k==="prep"){
        const oldPrep=existingCase?.prep||{};
        const changedGroups=new Set();
        const ungrouped=[];
        Object.keys(updates.prep||{}).forEach(pk=>{
          const oldVal=oldPrep[pk];
          const newVal=updates.prep[pk];
          if(JSON.stringify(oldVal)===JSON.stringify(newVal)) return;
          const grp=Object.keys(PREP_GROUPS).find(g=>PREP_GROUPS[g].includes(pk));
          if(grp) changedGroups.add(grp);
          else ungrouped.push(pk);
        });
        changedGroups.forEach(g=>changes.push(GROUP_LABELS[g]||g));
        ungrouped.forEach(pk=>{
          const oldVal=oldPrep[pk];const newVal=updates.prep[pk];
          if(Array.isArray(newVal)){changes.push(`${pk} updated`);}
          else if(!newVal){changes.push(`${pk} cleared`);}
          else{changes.push(`${pk} updated`);}
        });
      } else if(k==="statusItems"){
        const oldSI=existingCase?.statusItems||{};
        const newSI=updates.statusItems||{};
        const siLabels={secondNote:"2nd Note",clothes:"Clothes",coffin:"Coffin",mccd:"MCCD/BO",photo:"Photo"};
        Object.keys(newSI).forEach(sk=>{
          if(JSON.stringify(oldSI[sk])!==JSON.stringify(newSI[sk])){
            const oldV=oldSI[sk]||"not set";
            const newV=newSI[sk]||"cleared";
            changes.push(`${siLabels[sk]||sk}: ${oldV} → ${newV}`);
          }
        });
      } else if(k==="billable"){
        const oldB=existingCase?.billable||{};
        const newB=updates.billable||{};
        const added=Object.keys(newB).filter(bk=>newB[bk]&&!oldB[bk]);
        const removed=Object.keys(oldB).filter(bk=>oldB[bk]&&!newB[bk]);
        if(added.length) changes.push(`Services added: ${added.join(", ")}`);
        if(removed.length) changes.push(`Services removed: ${removed.join(", ")}`);
      } else if(!["pendingChanges","acceptedAt","prepStatus"].includes(k)){
        const oldVal=existingCase?.[k];
        const newVal=updates[k];
        if(JSON.stringify(oldVal)===JSON.stringify(newVal)) return;
        const label=labels[k]||k;
        changes.push(`${label} changed to: ${fmt(newVal)}`);
      }
    });
    return changes.length>0?changes:["Case updated"];
  }

  async function upd(id,updates){
    try{
      const local=cases.find(x=>x.id===id);
      // Always start from the latest saved copy (a 2nd Note or another device may have changed it)
      let fresh=local;
      try{const rows=await sb(`cases?id=eq.${id}&select=*`);if(rows&&rows[0])fresh=dbToCase(rows[0]);}catch(e){}
      const merged={};
      Object.keys(updates).forEach(k=>{
        const nv=updates[k];
        if(["prep","billable","otherUsed","statusItems"].includes(k)&&nv&&typeof nv==="object"&&!Array.isArray(nv)){
          const base=local?.[k]||{},out={...(fresh?.[k]||{})};
          new Set([...Object.keys(base),...Object.keys(nv)]).forEach(key=>{
            if(JSON.stringify(base[key])!==JSON.stringify(nv[key])){ if(nv[key]===undefined) delete out[key]; else out[key]=nv[key]; }
          });
          merged[k]=out;
        } else merged[k]=nv;
      });
      updates=merged;
      const existingCase=fresh;
      const changeDescs=describeChanges(updates,local);
      const newChange={
        at:new Date().toISOString(),
        by:user?.name||"Unknown",
        role:user?.role||"",
        changes:changeDescs
      };
      const existingChanges=existingCase?.pendingChanges||[];
      const pendingChanges=[...existingChanges,newChange];
      const fullUpdates={...updates,pendingChanges};
      await updateCase(id,caseToDb({...existingCase,...fullUpdates}));
      onUpdateCase(id,{...existingCase,...fullUpdates});
      setSelCase(p=>p?.id===id?{...existingCase,...fullUpdates}:p);
      logActivity(user,"MORTUARY UPDATE","Updated case "+(existingCase?.caseRef||id),existingCase?.caseRef,id);
    }catch(err){alert("Save error: "+err.message);}
  }

  const newJobs=cases.filter(x=>x.status==="active"&&!x.acceptedAt).sort((a,b)=>new Date(a.checkedInAt||0)-new Date(b.checkedInAt||0));
  const changedCases=cases.filter(x=>x.acceptedAt&&x.pendingChanges?.length>0&&x.status==="active").sort((a,b)=>new Date(b.pendingChanges?.slice(-1)[0]?.at||0)-new Date(a.pendingChanges?.slice(-1)[0]?.at||0));

  if(!selFH) return (
    <>
      <div className="max-w-7xl mx-auto px-4 py-4">
      <BackBtn onClick={onBack} label="Back to Home"/>
      <h2 className="text-2xl font-black text-gray-900 mb-3">Mortuary</h2>
      {newJobs.length>0&&(<div className="mb-8"><div className="flex items-center gap-3 mb-4"><span className="w-3 h-3 bg-green-500 rounded-full animate-pulse"/><h3 className="text-sm font-black uppercase tracking-widest text-gray-700">New Jobs — {newJobs.length} case{newJobs.length>1?"s":""}</h3>
            <button onClick={async()=>{if(!window.confirm("Accept all "+newJobs.length+" new jobs?")) return;const now=new Date().toISOString();for(const x of newJobs){try{await updateCase(x.id,{accepted_at:now,prep_status:"not-started"});onUpdateCase(x.id,{acceptedAt:now,prepStatus:"not-started"});}catch(e){alert("Error: "+e.message);break;}}}} className="text-xs font-black uppercase tracking-widest text-white bg-green-600 hover:bg-green-700 rounded-lg px-3 py-1.5 transition">✅ ACCEPT ALL</button>
            <button onClick={()=>{const w=window.open("","_blank");w.document.write("<html><head><title>New Jobs</title><style>body{font-family:Arial,sans-serif;padding:20px}table{width:100%;border-collapse:collapse}th{background:#111;color:#fff;padding:8px;text-align:left}td{padding:8px;border-bottom:1px solid #ddd}h2{margin-bottom:16px}</style></head><body><h2>New Jobs — "+new Date().toLocaleDateString("en-AU")+"</h2><table><tr><th>Case Ref</th><th>Deceased</th><th>Funeral Director</th><th>Checked In</th></tr>"+newJobs.map(x=>"<tr><td>"+x.caseRef+"</td><td>"+(x.lastName||"").toUpperCase()+", "+x.firstName+"</td><td>"+(x.funeralHomeName||"")+"</td><td>"+(x.checkedInAt?fmtDTDay(x.checkedInAt):"—")+"</td></tr>").join("")+"</table></body></html>");w.document.close();w.print();}} className="text-xs font-black uppercase tracking-widest text-gray-500 border border-gray-300 rounded-lg px-3 py-1.5 hover:border-gray-700 transition">🖨 PRINT LIST</button></div><div className="space-y-3">{newJobs.map(x=>(<div key={x.id} className="bg-white border-2 border-green-400 rounded-2xl p-5"><div className="flex items-start justify-between gap-4"><div><div className="text-lg font-black text-gray-900">{(x.lastName||"").toUpperCase()}, {x.firstName}</div><div className="text-sm text-gray-500 mt-0.5">{x.caseRef} · {x.funeralHomeName}</div><div className="text-xs text-gray-400 mt-0.5">Checked in: {x.checkedInAt?fmtDTDay(x.checkedInAt):"—"}</div></div><div className="flex gap-2 shrink-0"><AdminDeleteCase small c={x} user={user} onDeleted={()=>onUpdateCase(x.id,{acceptedAt:new Date().toISOString(),status:"deleted",checkedOut:true})}/><button onClick={async()=>{try{await updateCase(x.id,{accepted_at:new Date().toISOString(),prep_status:"not-started"});onUpdateCase(x.id,{acceptedAt:new Date().toISOString(),prepStatus:"not-started"});}catch(e){alert(e.message);}}} className="shrink-0 px-5 py-3 rounded-xl bg-green-600 text-white font-black text-sm uppercase hover:bg-green-700 transition">ACCEPT</button></div></div></div>))}</div><div className="border-t-2 border-gray-100 my-6"/></div>)}
      {changedCases.length>0&&<div className="mb-6">
        <div className="flex items-center gap-2 mb-3"><span className="w-3 h-3 bg-orange-500 rounded-full animate-pulse"/><span className="text-sm font-black uppercase tracking-widest text-orange-600">Changes Made — {changedCases.length}</span></div>
        <div className="space-y-3">
          {changedCases.map(x=>(
            <div key={x.id} className="bg-orange-50 border-2 border-orange-400 rounded-2xl p-4">
              <div className="flex items-start justify-between gap-3">
                <div>
                  <div className="text-lg font-black text-gray-900">{(x.lastName||"").toUpperCase()}, {x.firstName}</div>
                  <div className="text-sm text-gray-500">{x.caseRef} · {x.funeralHomeName}</div>
                  <ul className="mt-2 space-y-0.5">{x.pendingChanges.slice(-5).map((ch,i)=><li key={i} className="text-xs text-orange-700">· {ch.by} ({new Date(ch.at).toLocaleString("en-AU",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"})}): {ch.changes.join(", ")}</li>)}</ul>
                </div>
                <button onClick={async()=>{
                  try{
                    await updateCase(x.id,caseToDb({...x,pendingChanges:[]}));
                    onUpdateCase(x.id,{pendingChanges:[]});
                  }catch(err){alert("Error: "+err.message);}
                }} className="shrink-0 px-4 py-2 rounded-xl bg-orange-500 text-white font-black text-xs uppercase hover:bg-orange-600 transition">ACCEPT</button>
              </div>
            </div>
          ))}
        </div>
        <div className="border-t-2 border-gray-100 my-6"/>
      </div>}
      {toAccounts.length>0&&<div className="mb-6">
        <div className="text-sm font-black uppercase tracking-widest text-gray-900 mb-3">📧 Checked Out — Send to Accounts · {toAccounts.length}</div>
        {toAccounts.length>1&&<div className="bg-gray-50 border border-gray-200 rounded-2xl p-3 mb-3 flex flex-col sm:flex-row sm:items-center gap-3">
          <label className="flex items-center gap-3 cursor-pointer font-black text-sm uppercase tracking-wide flex-1">
            <input type="checkbox" checked={allTicked} onChange={e=>setAccSel(e.target.checked?Object.fromEntries(toAccounts.map(x=>[x.id,true])):{})} className="w-6 h-6 accent-gray-900"/>Tick all ({toAccounts.length})</label>
          <button type="button" onClick={sendTicked} disabled={!accTicked.length||!!accBusy} className="px-5 py-3 rounded-xl bg-gray-900 text-white font-black text-sm uppercase hover:bg-gray-700 disabled:opacity-40">{accBusy||`📧 Send ${accTicked.length?accTicked.length+" ":""}to Accounts`}</button>
        </div>}
        {accMsg&&<p className={"text-sm font-bold mb-3 "+(accMsg.includes("not sent")?"text-amber-700":"text-green-700")}>{accMsg}</p>}
        <div className="space-y-2">{toAccounts.map(x=>(
          <div key={x.id} className={"bg-white border-2 rounded-2xl p-4 flex items-center justify-between gap-3 "+(accSel[x.id]?"border-green-600":"border-gray-900")}>
            {toAccounts.length>1&&<input type="checkbox" checked={!!accSel[x.id]} onChange={e=>setAccSel(o=>({...o,[x.id]:e.target.checked}))} className="w-6 h-6 shrink-0 accent-gray-900" aria-label={"Tick "+x.caseRef}/>}
            <button type="button" onClick={()=>{setSelFH(FUNERAL_HOMES.find(f=>f.id===x.funeralHomeId)||{id:x.funeralHomeId,name:x.funeralHomeName});setSelCase(x);}} className="text-left min-w-0 flex-1">
              <div className="text-lg font-black text-gray-900 underline">{(x.lastName||"").toUpperCase()}, {x.firstName}</div>
              <div className="text-sm text-gray-500">{x.caseRef} · {x.funeralHomeName} · Checked out {fmtDTDay(x.checkout.checkedOutAt)}</div>
            </button>
            <SendToAccountsBtn c={x} user={user} onUpdateCase={onUpdateCase} compact/>
          </div>))}</div>
        <div className="border-t-2 border-gray-100 my-6"/>
      </div>}
      <h3 className="text-sm font-black uppercase tracking-widest text-gray-500 mb-4">Funeral Directors</h3>
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
        {sortAlpha(FUNERAL_HOMES,"name").map(fh=>{
          const has=!!(byFH[fh.id]?.length);
          const hasNew=byFH[fh.id]?.some(x=>!x.acceptedAt);
          const hasChanges=byFH[fh.id]?.some(x=>x.pendingChanges?.length>0);
      return <button key={fh.id} disabled={!has} onClick={()=>setSelFH(fh)} className={`relative py-4 px-2 rounded-2xl border-2 text-xs sm:text-sm font-bold text-center transition ${has?(hasChanges?"border-orange-400 bg-orange-50 text-gray-900 hover:border-orange-600":"border-gray-200 hover:border-gray-900 bg-white text-gray-900"):"border-gray-100 bg-gray-50 text-gray-300 cursor-not-allowed"}`}>{hasNew&&<span className="absolute top-2 right-2 w-3 h-3 bg-green-500 rounded-full border-2 border-white animate-pulse"/>}{hasChanges&&<span className="absolute top-2 left-2 w-3 h-3 bg-orange-500 rounded-full border-2 border-white animate-pulse"/>}{fh.name}{has&&<div className="text-xs font-normal text-gray-400 mt-1">{byFH[fh.id].length} case{byFH[fh.id].length>1?"s":""}</div>}</button>;
        })}
      </div>
      </div>
    </>
  );

  const fhCasesRaw=(byFH[selFH.id]||[]);
  const fhCases=[
    ...fhCasesRaw.filter(x=>!x.acceptedAt).sort((a,b)=>a.lastName.localeCompare(b.lastName)),
    ...fhCasesRaw.filter(x=>x.acceptedAt&&(x.prepStatus||"not-started")==="not-started").sort((a,b)=>a.lastName.localeCompare(b.lastName)),
    ...fhCasesRaw.filter(x=>x.acceptedAt&&x.prepStatus==="in-progress").sort((a,b)=>a.lastName.localeCompare(b.lastName)),
    ...fhCasesRaw.filter(x=>x.acceptedAt&&x.prepStatus==="completed").sort((a,b)=>a.lastName.localeCompare(b.lastName)),
  ];

  if(!selCase) return (
    <div className="max-w-7xl mx-auto px-4 py-4">
      <BackBtn onClick={()=>setSelFH(null)} label="Back to Funeral Directors"/>
      <h2 className="text-2xl font-black text-gray-900 mb-1">{selFH.name}</h2>
      <p className="text-gray-500 text-sm mb-6">Select deceased</p>
      <div className="space-y-3">
      {fhCasesRaw.some(x=>!x.acceptedAt)&&<div className="mb-2 px-1"><span className="text-xs font-black uppercase tracking-widest text-green-600">New Cases</span></div>}
        {fhCases.map(c=>(
          <button key={c.id} onClick={()=>setSelCase(c)} className={`w-full rounded-2xl p-5 text-left transition border-2 ${c.pendingChanges?.length>0?"bg-orange-50 border-orange-400 hover:border-orange-600":"bg-white border-gray-200 hover:border-gray-900"}`}>
            <div className="flex items-center justify-between">
              <div>
                <div className="text-xl font-black text-gray-900">{(c.lastName||"").toUpperCase()}, {c.firstName} — <span className="text-base font-bold text-gray-500">{sexShort(c.sex)}</span></div>
                <div className="text-sm text-gray-500 mt-1">{c.caseRef} · DOD: {fmt(c.dod)}</div>
                {c.pendingChanges?.length>0&&<div className="mt-2 text-xs font-black text-orange-600 uppercase">⚠ Changes made:</div>}
                {c.pendingChanges?.length>0&&<ul className="mt-1 space-y-0.5">{c.pendingChanges.slice(-5).map((ch,i)=><li key={i} className="text-xs text-orange-700">· {ch.by} ({new Date(ch.at).toLocaleString("en-AU",{day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"})}): {ch.changes.join(", ")}</li>)}</ul>}
              </div>
              <StatusDot status={c.prepStatus||"not-started"}/>
            </div>
          </button>
        ))}
      </div>
    </div>
  );

  const c=cases.find(x=>x.id===selCase.id)||selCase,prep=c.prep||{},billable=c.billable||{},otherUsed=c.otherUsed||{},statusItems=c.statusItems||{};
  const updPrep=(k,v)=>upd(c.id,{prep:{...prep,[k]:v}});
  const updPrepMulti=(updates)=>upd(c.id,{prep:{...prep,...updates}});
  const updBill=(k,v)=>upd(c.id,{billable:{...billable,[k]:v}});
  const updOther=(k,v)=>upd(c.id,{otherUsed:{...otherUsed,[k]:v}});
  const updStatus=(k,v)=>upd(c.id,{statusItems:{...statusItems,[k]:v}});
  const bookedSlots=getBookedSlots(cases,c.id);
  const isAdmin=user?.role==="admin";

  async function handleStatus(status){
    if(status==="completed"){
      if(window.confirm("Are you sure this case is finished?")){
        const firstTime=c.prepStatus!=="completed";
        await upd(c.id,{prepStatus:"completed"});
        const fhContacts=c.funeralHomeId==="OTHER"?[]:getFHContacts(c.funeralHomeId);
        const to=[MORTUARY_EMAIL,...fhContacts].join(",");
        const subj=encodeURIComponent(`T/L ${c.firstName} ${c.lastName} is now ready for departure`);
        let noteLines=[];try{const nn=await sb(`second_notes?select=answers,funeral_home_id&case_id=eq.${c.id}&order=submitted_at.desc&limit=1`);if(nn?.[0])noteLines=noteCheckLines(nn[0].funeral_home_id,nn[0].answers);}catch(e){}
        const body=encodeURIComponent(buildCompletedEmail(c, prep, billable, otherUsed, noteLines));
        if(firstTime){
          if(await sendAppEmail(to,decodeURIComponent(subj),decodeURIComponent(body)))alert("✓ Ready for departure — emailed to the FD & Mortuary");
          else{alert("The email couldn't be sent automatically — your mail app will open. Press Send.");window.location.href=`mailto:${to}?subject=${subj}&body=${body}`;}
        }
      }
    } else await upd(c.id,{prepStatus:status});
  }

  return (
    <>
    <button onClick={()=>setSelCase(null)} style={{position:"fixed",bottom:"24px",right:"16px",zIndex:9999,background:"#111",color:"#fff",border:"none",borderRadius:"50px",padding:"10px 18px",fontWeight:"900",fontSize:"12px",textTransform:"uppercase",letterSpacing:"1px",cursor:"pointer",boxShadow:"0 4px 16px rgba(0,0,0,0.35)"}}>⌂ HOME</button>
    <div className="w-full px-3 py-4" style={{maxWidth:"100%",boxSizing:"border-box"}}>
      <BackBtn onClick={()=>setSelCase(null)} label={`Back to ${selFH.name}`}/>
      {(isAdmin||user?.role==="mss")&&<div className="mb-3 flex flex-col sm:flex-row gap-2 sm:justify-end"><div className="sm:w-80"><ResendCheckInButton c={c} user={user}/></div>{isAdmin&&c.checkedOut&&<div className="sm:w-64"><AdminUndoCheckout c={c} user={user} onUpdateCase={onUpdateCase} onDone={()=>setSelCase({...c,checkedOut:false,checkout:null,status:"active"})}/></div>}      {isAdmin&&<div className="sm:w-64"><AdminDeleteCase c={c} user={user} onDeleted={()=>{onUpdateCase(c.id,{acceptedAt:c.acceptedAt||new Date().toISOString(),status:"deleted",checkedOut:true});setSelCase(null);}}/></div>}</div>}
      <div className="mb-4"><CaseViewCard c={{...c,prep}} isAdmin={isAdmin} onSave={updates=>upd(c.id,updates)} user={user} onFHChanged={u=>onUpdateCase(c.id,u)}/></div>
      {!c.acceptedAt&&(
        <button onClick={async()=>{await upd(c.id,{acceptedAt:new Date().toISOString(),prepStatus:"not-started"});}} className="w-full py-4 rounded-2xl bg-green-600 text-white font-black text-base uppercase tracking-wide mb-4 hover:bg-green-700 transition">✓ ACCEPT JOB</button>
      )}
      <PresenceDotInCase caseId={c.id} user={user}/>
      <div className="flex flex-wrap items-center gap-2 mb-3 rounded-xl px-3 py-2 bg-white border border-gray-200 text-gray-700">
        <span className="text-xs font-black uppercase tracking-widest text-gray-500 flex-1">Infectious disease?</span>
        {["Yes","No"].map(v=><button key={v} type="button" onClick={()=>updPrep("infectious",v)} className={"px-4 py-1.5 rounded-lg text-xs font-black uppercase border-2 "+((prep.infectious||"")===v?(v==="Yes"?"bg-red-600 text-white border-red-600":"bg-green-600 text-white border-green-600"):"border-gray-300 text-gray-500 hover:border-gray-500")}>{v==="Yes"?"☣ Yes":"No"}</button>)}
        {!prep.infectious&&<span className="text-[11px] font-bold text-amber-600">Not answered</span>}
      </div>
      <div className={s.card}>
        <p className={s.section}>Received — Checklist</p>
        <ChecklistItems c={c} prep={prep} statusItems={statusItems} updStatus={updStatus} updPrep={updPrep}/>
      </div>
      <SendToAccountsBtn c={c} user={user} onUpdateCase={onUpdateCase}/>
      <JobSheet isAdmin={user?.role==="admin"} c={c} prep={prep} billable={billable} upd={upd} handleStatus={handleStatus} onPacemaker={()=>setShowPacemakerCert(true)} onAcceptChanges={async()=>{try{await updateCase(c.id,caseToDb({...c,pendingChanges:[]}));onUpdateCase(c.id,{pendingChanges:[]});setSelCase(p=>p?.id===c.id?{...p,pendingChanges:[]}:p);}catch(err){alert("Error: "+err.message);}}}/>
      <div id="docsSection" className="mt-4"><DocumentSection key={docReload} caseId={c.id} filesDeletedAt={c.filesDeletedAt} backupFolder={c.backupFolder} funeralHomeName={c.funeralHomeName} lastName={c.lastName} dod={c.dod}/></div>

      {showPacemakerCert&&<PacemakerCertificate caseData={c} onClose={()=>setShowPacemakerCert(false)} onSaved={()=>{setShowPacemakerCert(false);setDocReload(p=>p+1);}}/>}
    </div>
    </>
  );
}

// ─── JOB SHEET (what MSS did, for billing) ───────────────────────────────────
const JS_PREP=[
  {key:"BP",label:"Basic Prep",prep:"Basic Prep",v:{std:"BP",os:"BP1"}},
  {key:"TP",label:"Temp Preservation",prep:"Temp Prep",v:{std:"TP",os:"TP1",cor:"TPC",coros:"TPC1"}},
  {key:"FE",label:"Full Embalm",prep:"Full Embalm",v:{std:"FE",os:"FE1",cor:"FEC",coros:"FEC1"}},
  {key:"NSNA",label:"NSNA",prep:"No Prep",v:{std:"NSNA"}},
  {key:"RSF",label:"Repatriation",prep:"Repatriation",v:{std:"RSF"}},
];
const JS_PREP_CODES=["BP","TP","FE","BP1","TP1","FE1","TPC","FEC","TPC1","FEC1","NSNA","RSF"];
const JS_VERSIONS=[["std","Standard"],["os","Oversize (OS)"],["cor","Coroner"],["coros","Coroner + OS"]];
const JS_QTY=["CL","CS","CL4","CL5","WD","NPL","NPS","BB","TYV","SHR","CP"];
const JS_SECTIONS=[
  {title:"Services & Care",codes:["DRS","PR","FP","ASP","BSI","REC","INF","HCO","AHB","DRR","DID","DIV","OPC"]},
  {title:"Items Used",codes:["BB","TYV","SHR","CP","CL","CS","NPL","NPS","NPE","CPT","GA"]},
  {title:"Rooms & AV",codes:["VR1","VRH","FMR","FMR2","CPL","WD","AV","LS1","LS2","SSO","SSM"]},
  {title:"Transfers – Hospital / Coroner",codes:["TH1","TH2","TH3","TH4","TH5","TH6"]},
  {title:"Transfers – Home / Residential",codes:["TR1","TR2","TR3","TR4","TR5","TR6"]},
  {title:"ED & Hearse",codes:["ED1","ED2","ED3","ED4","EDS","HH1","HH2"]},
  {title:"Labour & Accommodation",codes:["CL4","CL5","ACC"]},
];
const jsMoney=n=>"$"+(Math.round(n*100)/100).toLocaleString("en-AU",{minimumFractionDigits:n%1?2:0,maximumFractionDigits:2});
function calNights(a,b){const d=x=>Date.parse(new Date(x).toLocaleDateString("en-CA",{timeZone:"Australia/Sydney"}));return Math.max(1,Math.round((d(b)-d(a))/86400000));}
const jsNights=c=>{if(!c.checkedInAt)return 1;return calNights(c.checkedInAt,c.checkout?.checkedOutAt||new Date());};
const jsQty=(b,code,c)=>code==="ACC"?(b.ACC?jsNights(c):0):typeof b[code]==="number"?b[code]:(b[code]?(parseInt(c.prep?.[code+"Qty"])||1):0);
function JobSheet({isAdmin,c,prep,billable,upd,handleStatus,onPacemaker,onAcceptChanges}){
  const [coEdit,setCoEdit]=useState(null);
  const toLocalIn=x=>{const d=new Date(x);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
  async function saveCoDate(){const d=new Date(coEdit);if(isNaN(d))return;if(c.checkedInAt&&d<new Date(c.checkedInAt)){alert("Check out can't be before check in.");return;}
    await upd(c.id,{checkout:{...c.checkout,checkedOutAt:d.toISOString(),checkedOutAtSetBy:"Admin"}});setCoEdit(null);}
  const [note,setNote]=useState(null);const [showPlate,setShowPlate]=useState(false);
  useEffect(()=>{let live=true;sb(`second_notes?case_id=eq.${c.id}&answers->>_drOnly=is.null&select=pdf_path,submitted_at,answers&order=submitted_at.desc&limit=1`).then(r=>{if(live&&Array.isArray(r)&&r[0])setNote(r[0]);}).catch(()=>{});return()=>{live=false;};},[c.id]);
  const b=billable||{};
  const curCode=JS_PREP_CODES.find(k=>b[k]);
  const curBase=JS_PREP.find(p=>Object.values(p.v).includes(curCode));
  const curVer=curBase?Object.entries(curBase.v).find(([,v])=>v===curCode)?.[0]:"std";
  const askedPrep=(prep.prepOptions||[])[0];
  function pickPrep(base,ver){
    const nb={...b};JS_PREP_CODES.forEach(k=>delete nb[k]);
    let nextPrep=prep.prepOptions||[];
    if(base){const code=base.v[ver]||base.v.std;nb[code]=true;nextPrep=[base.prep];}
    upd(c.id,{billable:nb,prep:{...prep,prepOptions:nextPrep}});
  }
  const setQty=(code,n)=>{const nb={...b};if(n<=0)delete nb[code];else nb[code]=JS_QTY.includes(code)?n:true;upd(c.id,{billable:nb});};
  const lines=Object.keys(b).filter(k=>b[k]&&SERVICE_LABELS_XERO[k]).map(k=>({code:k,label:SERVICE_LABELS_XERO[k],qty:jsQty(b,k,c),price:PRICE_LIST[k]||0}));
  const total=lines.reduce((s2,l)=>s2+l.qty*l.price,0);
  const chip=on=>"w-full min-h-[48px] rounded-xl border-2 px-3 py-2 text-xs font-black text-left flex items-center justify-between gap-2 transition "+(on?"border-green-600 bg-green-50 text-green-800":"border-gray-200 bg-white text-gray-700 hover:border-gray-700");
  const card="bg-white border border-gray-200 rounded-2xl p-4 sm:p-5";
  const head="text-xs font-black uppercase tracking-widest text-gray-500 mb-3";
  const info=(l,v)=>(<div className="bg-gray-800 rounded-xl px-3 py-2"><div className="text-[10px] font-black uppercase tracking-widest text-gray-400">{l}</div><div className="text-sm font-bold">{v}</div></div>);
  return(
    <div className="space-y-4">
      <div className="bg-gray-900 text-white rounded-2xl p-4 sm:p-5">
        <div className="flex items-start justify-between gap-3 mb-3">
          <div><div className="text-xs font-black uppercase tracking-widest text-gray-400">Job Sheet · {c.caseRef}</div><div className="text-sm text-gray-300 mt-1">{c.funeralHomeName}</div></div>
          {note?.pdf_path
            ?<a href={getDocumentUrl(note.pdf_path)} target="_blank" rel="noreferrer" className="shrink-0 bg-white text-gray-900 rounded-xl px-4 py-3 text-xs font-black uppercase tracking-wide hover:bg-gray-100">📄 View 2nd Note</a>
            :<span className="shrink-0 text-xs font-bold text-gray-400 border border-gray-600 rounded-xl px-3 py-2">No 2nd Note yet</span>}
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
          {info("Checked in",c.checkedInAt?fmtDTDay(c.checkedInAt):"—")}
          {isAdmin&&c.checkout?.checkedOutAt
            ?<div className="bg-gray-800 rounded-xl px-3 py-2"><div className="flex items-center justify-between gap-2"><span className="text-[10px] font-black uppercase tracking-widest text-gray-400">Checked out</span>{coEdit===null&&<button type="button" onClick={()=>setCoEdit(toLocalIn(c.checkout.checkedOutAt))} className="text-[10px] font-black uppercase text-amber-300 hover:text-white">✎ Change</button>}</div>
              {coEdit===null
                ?<div className="text-sm font-bold">{fmtDTDay(c.checkout.checkedOutAt)}</div>
                :<div className="mt-1 space-y-1"><input type="datetime-local" value={coEdit} max={toLocalIn(new Date())} onChange={e=>setCoEdit(e.target.value)} className="w-full px-2 py-1 rounded text-gray-900 text-xs font-bold"/><div className="flex gap-1"><button type="button" onClick={saveCoDate} className="flex-1 py-1 rounded bg-green-600 text-white text-[10px] font-black uppercase">Save</button><button type="button" onClick={()=>setCoEdit(null)} className="flex-1 py-1 rounded bg-gray-600 text-white text-[10px] font-black uppercase">Cancel</button></div></div>}
            </div>
            :info("Checked out",c.checkout?.checkedOutAt?fmtDTDay(c.checkout.checkedOutAt):"Still in care")}
          {info("Nights",jsNights(c)+(c.checkout?.checkedOutAt?"":" so far"))}
          {info("Prep",askedPrep||"—")}
          {info("Disposition",prep.disposition||"—")}
        </div>
      </div>

      <div className="flex flex-col sm:flex-row gap-3">
        {c.pendingChanges?.length>0&&<button onClick={onAcceptChanges} className="flex-1 py-3 rounded-xl bg-orange-500 text-white font-black text-sm uppercase hover:bg-orange-600 transition">✓ Accept Changes</button>}
        <button onClick={()=>printCaseLabel({...c,prep})} className="flex-1 py-3 rounded-xl border-2 border-gray-900 text-gray-900 font-black text-sm uppercase hover:bg-gray-50 transition">🏷️ Print Label</button>
        <button onClick={()=>setShowPlate(true)} className="flex-1 py-3 rounded-xl border-2 border-gray-900 text-gray-900 font-black text-sm uppercase hover:bg-gray-50 transition">🪧 Name Plate</button>
        {showPlate&&<NamePlateModal c={c} plate={note?.answers?._plate} onClose={()=>setShowPlate(false)} onDownloaded={(pl,pe)=>upd(c.id,{prep:{...prep,namePlate:{at:new Date().toISOString(),by:"",plate:pl,person:pe}}})}/>}
        <button onClick={onPacemaker} className="flex-1 py-3 rounded-xl bg-amber-500 text-white font-black text-sm uppercase hover:bg-amber-600 transition">📋 Pacemaker Cert</button>
      </div>

      <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px] items-start">
        <div className="space-y-4 min-w-0">
          <div className={card}>
            <div className="flex items-baseline justify-between gap-2 mb-3"><p className={head+" mb-0"}>Preparation — choose one</p></div>
            <div className="grid grid-cols-2 sm:grid-cols-5 gap-2 mb-3">
              {JS_PREP.map(p=>{const on=curBase?.key===p.key;const code=p.v[on?curVer:"std"]||p.v.std;return(
                <button key={p.key} type="button" onClick={()=>pickPrep(on?null:p,curVer)} className={"min-h-[56px] rounded-xl border-2 text-sm font-black flex flex-col items-center justify-center transition "+(on?"bg-gray-900 text-white border-gray-900":"bg-white text-gray-700 border-gray-200 hover:border-gray-700")}>
                  {p.label}<span className={"text-[11px] font-bold "+(on?"text-gray-300":"text-gray-500")}>{code} · {jsMoney(PRICE_LIST[code]||0)}</span></button>);})}
            </div>
            {curBase&&Object.keys(curBase.v).length>1&&<div className="flex flex-wrap items-center gap-2">
              <span className="text-xs font-bold text-gray-600">Version:</span>
              {JS_VERSIONS.filter(([k])=>curBase.v[k]).map(([k,l])=><button key={k} type="button" onClick={()=>pickPrep(curBase,k)} className={"min-h-[36px] px-3 rounded-full border-2 text-xs font-black transition "+(curVer===k?"bg-gray-900 text-white border-gray-900":"bg-white text-gray-700 border-gray-200 hover:border-gray-700")}>{l}</button>)}
            </div>}
          </div>

          {JS_SECTIONS.map(sec=>(
            <div key={sec.title} className={card}>
              <p className={head}>{sec.title}</p>
              <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-2">
                {sec.codes.map(code=>{const q=jsQty(b,code,c),on=q>0,label=SERVICE_LABELS_XERO[code]||code,price=PRICE_LIST[code]||0;
                  if(on&&JS_QTY.includes(code))return(
                    <div key={code} className={chip(true)}>
                      <span className="min-w-0">{label}</span>
                      <span className="flex items-center gap-1 shrink-0">
                        <button type="button" aria-label="One less" onClick={()=>setQty(code,q-1)} className="w-8 h-8 rounded-lg border border-green-300 bg-white font-black">−</button>
                        <span className="w-5 text-center">{q}</span>
                        <button type="button" aria-label="One more" onClick={()=>setQty(code,q+1)} className="w-8 h-8 rounded-lg border border-green-300 bg-white font-black">+</button>
                      </span>
                    </div>);
                  return(<button key={code} type="button" onClick={()=>setQty(code,on?0:1)} className={chip(on)}>
                    <span className="min-w-0">{on?"✓ ":""}{label}{code==="ACC"&&on?` × ${q}`:""}</span>
                    <span className={"shrink-0 font-bold "+(on?"":"text-gray-500")}>{jsMoney(price)}{code==="ACC"?"/night":""}</span></button>);})}
              </div>
            </div>
          ))}
        </div>

        <div className="space-y-4">
          <div className="bg-white border-2 border-gray-900 rounded-2xl p-4">
            <p className={head}>This job so far</p>
            {lines.length===0&&<p className="text-sm text-gray-400">Nothing added yet.</p>}
            <div className="space-y-1.5">{lines.map(l=><div key={l.code} className="flex justify-between gap-2 text-sm"><span className="min-w-0">{l.code} · {l.label}{l.qty>1?` × ${l.qty}`:""}</span><b className="shrink-0">{jsMoney(l.qty*l.price)}</b></div>)}</div>
            <div className="border-t border-gray-200 mt-3 pt-3 flex justify-between items-baseline"><span className="text-xs font-black tracking-wide">TOTAL (INC GST)</span><span className="text-2xl font-black">{jsMoney(total)}</span></div>
            <p className="text-[11px] text-gray-500 mt-2">Goes to Invoicing and the Xero export.</p>
          </div>
          <div className="bg-white border border-gray-200 rounded-2xl p-4">
            <p className={head}>Status</p>
            <div className="grid grid-cols-3 lg:grid-cols-1 gap-2">
              {[["not-started","Not Started","bg-red-500"],["in-progress","In Progress","bg-amber-500"],["completed","Completed","bg-green-600"]].map(([val,label,col])=>(
                <button key={val} onClick={()=>handleStatus(val)} className={`py-3 rounded-xl text-white font-black text-sm transition ${col} ${c.prepStatus===val?"ring-4 ring-offset-2 ring-gray-300":"opacity-60 hover:opacity-100"}`}>{label}</button>
              ))}
            </div>
          </div>
          <div className="bg-white border border-gray-200 rounded-2xl p-4">
            <label htmlFor="js-notes" className={head+" block"}>Notes</label>
            <textarea id="js-notes" className={`${s.inp} min-h-[100px]`} value={prep.comments||""} onChange={e=>upd(c.id,{prep:{...prep,comments:e.target.value}})} placeholder="Anything unusual about this job…"/>
          </div>
          <div className="bg-white border border-gray-200 rounded-2xl p-4">
            <p className={head}>Valuables found in mortuary</p>
            <div className="flex gap-2">
              <button type="button" onClick={()=>upd(c.id,{prep:{...prep,mortuaryValuables:"Yes"}})} className={`flex-1 py-2.5 rounded-xl border-2 font-black text-xs uppercase ${prep.mortuaryValuables==="Yes"?"bg-green-600 text-white border-green-600":"border-gray-300 text-gray-600"}`}>Yes</button>
              <button type="button" onClick={()=>upd(c.id,{prep:{...prep,mortuaryValuables:"No",mortuaryValuablesText:""}})} className={`flex-1 py-2.5 rounded-xl border-2 font-black text-xs uppercase ${prep.mortuaryValuables==="No"?"bg-gray-900 text-white border-gray-900":"border-gray-300 text-gray-600"}`}>No</button>
            </div>
            {prep.mortuaryValuables==="Yes"&&<textarea className={`${s.inp} min-h-[70px] mt-2`} value={prep.mortuaryValuablesText||""} onChange={e=>upd(c.id,{prep:{...prep,mortuaryValuablesText:e.target.value}})} placeholder="e.g. Gold wedding ring…"/>}
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── SEND TO ACCOUNTS (staff, after check-out) ─────────────────────────────────────────
const INVOICE_EMAIL="scott@mortuarysupport.com.au";
function jsLines(c,b){return Object.keys(b||{}).filter(k=>b[k]&&SERVICE_LABELS_XERO[k]).map(k=>({code:k,label:SERVICE_LABELS_XERO[k],qty:jsQty(b,k,c),price:PRICE_LIST[k]||0}));}
async function buildJobSheetPdf(c,prep,b,by){
  const {PDFDocument,rgb,StandardFonts}=await import("https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.esm.min.js");
  const T=v=>String(v??"").replace(/[–—]/g,"-").replace(/×/g,"x").replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/[^\x20-\x7E\xA0-\xFF]/g,"");
  const doc=await PDFDocument.create();const f=await doc.embedFont(StandardFonts.Helvetica);const fb=await doc.embedFont(StandardFonts.HelveticaBold);
  let page=doc.addPage([595.28,841.89]);let y=800;const L=40,R=555;
  const text=(t,x,o={})=>page.drawText(T(t),{x,y,size:o.size||10,font:o.bold?fb:f,color:o.grey?rgb(.4,.4,.4):rgb(0,0,0)});
  const right=(t,x,o={})=>{const w=(o.bold?fb:f).widthOfTextAtSize(T(t),o.size||10);text(t,x-w,o);};
  const fit=(t,max,o={})=>{let s=T(t);const ft=o.bold?fb:f;while(s.length>3&&ft.widthOfTextAtSize(s,o.size||10)>max)s=s.slice(0,-2);return s;};
  const line=()=>page.drawLine({start:{x:L,y:y},end:{x:R,y:y},thickness:.6,color:rgb(.8,.8,.8)});
  const nl=(n=14)=>{y-=n;if(y<60){page=doc.addPage([595.28,841.89]);y=800;}};
  text("MORTUARY SUPPORT SERVICES",L,{bold:true,size:9,grey:true});right("JOB SHEET",R,{bold:true,size:16});nl(26);
  text(`${(c.lastName||"").toUpperCase()}, ${c.firstName||""}`,L,{bold:true,size:18});right(c.caseRef||"",R,{bold:true,size:12});nl(18);
  text(c.funeralHomeName||"",L,{size:11});nl(20);line();nl(16);
  const info=[["Checked in",c.checkedInAt?fmtDTDay(c.checkedInAt):"-"],["Checked out",c.checkout?.checkedOutAt?fmtDTDay(c.checkout.checkedOutAt):"Still in care"],["Nights",String(jsNights(c))],["Preparation",(prep.prepOptions||[])[0]||"-"],["Disposition",prep.disposition||"-"],["Checked out by",by||"-"]];
  info.forEach(([k,v])=>{text(k,L,{bold:true,grey:true,size:9});text(v,L+90);nl(15);});
  nl(8);line();nl(16);
  text("CODE",L,{bold:true,size:9,grey:true});text("ITEM",L+55,{bold:true,size:9,grey:true});right("QTY",L+360,{bold:true,size:9,grey:true});right("UNIT",L+440,{bold:true,size:9,grey:true});right("AMOUNT",R,{bold:true,size:9,grey:true});nl(16);
  const lines=jsLines(c,b);let total=0;
  if(!lines.length){text("No items recorded",L,{grey:true});nl();}
  lines.forEach(l=>{const amt=l.qty*l.price;total+=amt;text(l.code,L,{bold:true});text(fit(l.label,290),L+55);right(String(l.qty),L+360);right(jsMoney(l.price),L+440);right(jsMoney(amt),R);nl(15);});
  nl(4);line();nl(18);
  right("TOTAL (INC GST)",L+440,{bold:true});right(jsMoney(total),R,{bold:true,size:14});nl(14);
  right("includes GST of",L+440,{grey:true,size:9});right(jsMoney(total/11),R,{grey:true,size:9});nl(24);
  const para=(h,v)=>{if(!v)return;text(h,L,{bold:true,size:9,grey:true});nl(14);T(v).split(/\n/).forEach(p=>{let s="";p.split(" ").forEach(w=>{if(f.widthOfTextAtSize(s+w+" ",10)>R-L){text(s,L);nl(13);s="";}s+=w+" ";});text(s,L);nl(13);});nl(8);};
  para("NOTES",prep.comments);
  para("VALUABLES FOUND IN MORTUARY",prep.mortuaryValuables==="Yes"?(prep.mortuaryValuablesText||"Yes"):prep.mortuaryValuables==="No"?"None":"");
  return {bytes:await doc.save(),lines,total};
}
async function sendJobSheet(c,prep,b,by){
  const safe=v=>String(v||"").replace(/[^a-zA-Z0-9]/g,"_");
  let pdfUrl="",lines=jsLines(c,b),total=lines.reduce((s2,l)=>s2+l.qty*l.price,0),noteUrl="";
  try{
    const r=await buildJobSheetPdf(c,prep,b,by);
    const name=`JOBSHEET_${safe(c.caseRef)}_${safe(c.lastName)}.pdf`;const path=`${c.id}/${Date.now()}_${name}`;
    const up=await fetch(`${SUPABASE_URL}/storage/v1/object/${STORAGE_BUCKET}/${path}`,{method:"POST",headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,"Content-Type":"application/pdf","x-upsert":"true"},body:r.bytes});
    if(up.ok){pdfUrl=getDocumentUrl(path);fetch(SUPABASE_URL+"/rest/v1/case_documents",{method:"POST",headers:{"Content-Type":"application/json",apikey:SUPABASE_KEY,Authorization:"Bearer "+SUPABASE_KEY,Prefer:"return=minimal"},body:JSON.stringify({case_id:c.id,name,path,size:r.bytes.length,uploaded_at:new Date().toISOString()})}).catch(()=>{});}
  }catch(e){console.error("Job sheet PDF",e);}
  try{const n=await sb(`second_notes?case_id=eq.${c.id}&select=pdf_path&order=submitted_at.desc&limit=1`);if(Array.isArray(n)&&n[0]?.pdf_path)noteUrl=getDocumentUrl(n[0].pdf_path);}catch(e){}
  const who=`${(c.lastName||"").toUpperCase()}, ${c.firstName||""}`;
  const subject=`Job Sheet – ${who} (${c.caseRef}) – ${c.funeralHomeName||""} – ready to invoice`;
  const body=[
    `JOB SHEET – ${who}`,
    `Case: ${c.caseRef}`,`Funeral Director: ${c.funeralHomeName||"—"}`,
    `Checked in: ${c.checkedInAt?fmtDTDay(c.checkedInAt):"—"}`,
    `Checked out: ${c.checkout?.checkedOutAt?fmtDTDay(c.checkout.checkedOutAt):"—"}${by?" by "+by:""}`,
    `Preparation: ${(prep.prepOptions||[])[0]||"—"}`,"",
    `ITEMS`,
    ...(lines.length?lines.map(l=>`${l.code} – ${l.label}: ${l.qty} × ${jsMoney(l.price)} = ${jsMoney(l.qty*l.price)}`):["No items recorded"]),"",
    `TOTAL (INC GST): ${jsMoney(total)}`,"",
    ...(prep.comments?[`Notes: ${prep.comments}`,""]:[]),
    `Job Sheet PDF: ${pdfUrl||"(could not be created)"}`,
    `2nd Note PDF: ${noteUrl||"No 2nd Note on file"}`,"",
    `The Team at Mortuary Support Services`,
  ].join("\n");
  try{
    const res=await fetch("/api/send-email",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({to:[INVOICE_EMAIL],subject,text:body,attachments:[pdfUrl&&{filename:`Job Sheet ${c.caseRef}.pdf`,path:pdfUrl},noteUrl&&{filename:`2nd Note ${c.caseRef}.pdf`,path:noteUrl}].filter(Boolean)})});
    if(res.ok)return {status:"sent"};
  }catch(e){}
  return {status:"mailto",href:`mailto:${INVOICE_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`};
}

async function sendToAccounts(c,user,onUpdateCase){
  const prep=c.prep||{};
  const r=await sendJobSheet(c,prep,c.billable||{},c.checkout?.checkedOutBy||"");
  if(r.status==="mailto")window.location.href=r.href;
  const np={...prep,jobSheetSentAt:new Date().toISOString(),jobSheetSentBy:user?.name||""};
  try{await updateCase(c.id,{prep:np});onUpdateCase(c.id,{prep:np});}catch(e){}
  return r.status;
}
function SendToAccountsBtn({c,user,onUpdateCase,compact}){
  const [busy,setBusy]=useState(false);
  const out=!!c.checkout?.checkedOutAt;const sent=c.prep?.jobSheetSentAt;
  async function go(){if(!out||busy)return;setBusy(true);try{const st=await sendToAccounts(c,user,onUpdateCase);if(st==="sent")alert("Job Sheet and 2nd Note sent to accounts.");}catch(e){alert("Couldn't send: "+e.message);}setBusy(false);}
  if(compact)return <button type="button" onClick={go} disabled={busy} className="shrink-0 px-4 py-3 rounded-xl bg-gray-900 text-white font-black text-xs uppercase hover:bg-gray-700 transition">{busy?"Sending…":"📧 Send to Accounts"}</button>;
  return(<div className="mb-4">
    <button type="button" onClick={go} disabled={!out||busy} className={"w-full py-4 rounded-2xl font-black text-base uppercase tracking-wide transition "+(!out?"bg-gray-200 text-gray-400 cursor-not-allowed":sent?"bg-green-600 text-white hover:bg-green-700":"bg-gray-900 text-white hover:bg-gray-700")}>
      {busy?"Sending…":!out?"🔒 Send to Accounts":sent?"✓ Sent to Accounts — tap to send again":"📧 Send to Accounts"}
    </button>
    <p className="text-xs text-gray-500 text-center mt-1">{!out?"Available once the body has been checked out":sent?`Sent ${fmtDTDay(sent)}${c.prep?.jobSheetSentBy?" by "+c.prep.jobSheetSentBy:""} · Job Sheet + 2nd Note to ${INVOICE_EMAIL}`:`Job Sheet + 2nd Note to ${INVOICE_EMAIL}`}</p>
  </div>);
}

// Sends an app email via /api/send-email (Resend). Returns true if sent.
async function sendAppEmail(to,subject,text,attachments){
  try{const list=String(to).split(",").map(x=>x.trim()).filter(Boolean);
    const r=await fetch("/api/send-email",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({to:list,subject,text,attachments:attachments||[]})});
    return r.ok;}catch(e){return false;}
}
// ─── LEURA CREMATION CERTIFICATES (MSS NSNA) ─────────────────────────────────
function LeuraCertsView({user,cases,onBack}){
  // MSS NSNA cremation certificates from Leura (signed online after check-out)
  const[crem,setCrem]=useState([]);const[cremBusy,setCremBusy]=useState("");
  const loadCrem=()=>fetch(SUPABASE_URL+"/rest/v1/second_notes?select=id,case_id,case_ref,deceased_name,funeral_home_name,answers&answers->>_nsna=eq.true&order=submitted_at.desc&limit=80",{headers:{"apikey":SUPABASE_KEY,"Authorization":"Bearer "+SUPABASE_KEY}}).then(r=>r.json()).then(d=>setCrem(Array.isArray(d)?d:[])).catch(()=>{});
  React.useEffect(()=>{loadCrem();},[]);
  async function cremAction(n,action){
    const signed=!!n.answers?._crem?.signedAt, label=action==="resend-signed"?`Email the signed certificate for ${n.deceased_name} to ${n.funeral_home_name} again?`:`${n.answers?._crem?.sentAt?"Resend":"Send"} the signing link for ${n.deceased_name} to Leura Memorial Gardens?`;
    if(!window.confirm(label))return;
    setCremBusy(n.id);
    try{const r=await fetch("/api/crem",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action,noteId:n.id,resend:true,by:user?.name})});const j=await r.json().catch(()=>({}));
      if(!r.ok)throw new Error(j.error||"Couldn't send");
      logActivity(user,action==="resend-signed"?"CREM CERT RESENT TO FD":"CREM CERT LINK SENT",`${n.deceased_name}${signed?" → "+n.funeral_home_name:" → Leura"}`,n.case_ref||"",n.case_id||"");
      alert("✓ Sent");loadCrem();}catch(e){alert(e.message);}
    setCremBusy("");
  }
  async function cremDelete(n){
    const d=n.answers?._crem||{};
    if(!window.confirm(`Delete ${n.deceased_name} from Leura Certificates?${d.signedAt?"\n\nThe signed certificate stays saved on the case.":d.sentAt?"\n\nThe link already sent to Leura will stop working.":""}`))return;
    setCremBusy(n.id);
    try{const cur=(await sb(`second_notes?select=answers&id=eq.${n.id}`))?.[0]?.answers||{};
      if(cur._drOnly&&!cur._drref)await sb(`second_notes?id=eq.${n.id}`,{method:"DELETE"});
      else{const c2={...(cur._crem||{}),hidden:true,hiddenBy:user?.name||"",hiddenAt:new Date().toISOString()};delete c2.token;
        await sb(`second_notes?id=eq.${n.id}`,{method:"PATCH",body:JSON.stringify({answers:{...cur,_crem:c2}})});}
      logActivity(user,"CREM CERT DELETED",n.deceased_name,n.case_ref||"",n.case_id||"");
      setCrem(v=>v.filter(x=>x.id!==n.id));
    }catch(e){alert("Couldn't delete: "+(e.message||e));}
    setCremBusy("");
  }

  const [tab,setTab]=useState("open");
  const all=crem.filter(n=>!n.answers?._crem?.hidden);
  const isDone=n=>!!n.answers?._crem?.signedAt;
  const shown=tab==="open"?all.filter(n=>!isDone(n)):all.filter(isDone);
  const tabBtn=(k,l,n)=><button type="button" onClick={()=>setTab(k)} className={"px-4 py-2.5 rounded-xl border-2 text-sm font-black "+(tab===k?"bg-gray-900 border-gray-900 text-white":"bg-white border-gray-200 text-gray-700 hover:border-gray-700")}>{l} · {n}</button>;
  const crem2=shown;
  // Manually add a past (or any) MSS NSNA cremation
  const blankM={q:"",caseId:"",firstName:"",lastName:"",dob:"",dod:"",fhId:"",send:true};
  const [man,setMan]=useState(null),[manBusy,setManBusy]=useState(false),[manErr,setManErr]=useState("");
  const setM=(k,v)=>setMan(m=>({...m,[k]:v}));
  const mInp="w-full border-2 border-gray-200 rounded-xl px-3 py-2.5 text-base focus:border-gray-900 outline-none";
  const mLbl="text-xs font-black text-gray-500 uppercase";
  const fhList=[...FUNERAL_HOMES].sort((a,b)=>String(a.name).localeCompare(String(b.name)));
  const hits=man&&man.q.trim().length>=2&&!man.caseId?cases.filter(c=>`${c.firstName||""} ${c.lastName||""} ${c.caseRef||""}`.toLowerCase().includes(man.q.trim().toLowerCase())).slice(0,8):[];
  const pickCase=c=>setMan(m=>({...m,q:"",caseId:c.id,firstName:c.firstName||"",lastName:c.lastName||"",dob:String(c.dob||"").slice(0,10),dod:String(c.dod||"").slice(0,10),fhId:c.funeralHomeId||""}));
  async function saveManual(){
    setManErr("");
    const miss=[!man.firstName.trim()&&"first name",!man.lastName.trim()&&"surname",!man.dod&&"date of death",!man.fhId&&"funeral director"].filter(Boolean);
    if(miss.length)return setManErr("Still needed: "+miss.join(", "));
    const c=cases.find(x=>x.id===man.caseId), fh=FUNERAL_HOMES.find(f=>f.id===man.fhId)||{};
    const name=`${man.firstName.trim()} ${man.lastName.trim()}`;
    setManBusy(true);
    try{
      let noteId=null;
      if(c){const ex=(await sb(`second_notes?select=id,answers&case_id=eq.${c.id}&order=submitted_at.desc`))||[];
        const n=ex.find(x=>!x.answers?._drOnly)||ex[0];
        if(n){if(n.answers?._crem?.signedAt)throw new Error("Leura has already signed the certificate for "+name+".");
          noteId=n.id;await sb(`second_notes?id=eq.${n.id}`,{method:"PATCH",body:JSON.stringify({answers:{...(n.answers||{}),_nsna:true,_crem:{...(n.answers?._crem||{}),manual:true,hidden:false}}})});}}
      if(!noteId){noteId=crypto.randomUUID();
        await sb("second_notes",{method:"POST",body:JSON.stringify({id:noteId,funeral_home_id:man.fhId,funeral_home_name:fh.name||"",case_id:c?.id||null,case_ref:c?.caseRef||null,
          deceased_name:name,pdf_path:null,
          answers:{firstName:man.firstName.trim(),lastName:man.lastName.trim(),dob:man.dob,dod:man.dod,disposition:"Cremation",_drOnly:true,_nsna:true,_crem:{manual:true,addedBy:user?.name||""}},
          submitted_by:user?.name||"",submitted_role:user?.role||"",status:c?"linked":"awaiting",accepted_at:new Date().toISOString(),accepted_by:"Leura cert (manual)"})});}
      logActivity(user,"CREM CERT ADDED",`${name} (manual) → Leura`,c?.caseRef||"",c?.id||"");
      if(man.send){const r=await fetch("/api/crem",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"request",noteId,by:user?.name})});const j=await r.json().catch(()=>({}));
        if(!r.ok)throw new Error("Added, but couldn't email Leura: "+(j.error||"error")+". Use ✉ Send to Leura on the list.");
        logActivity(user,"CREM CERT LINK SENT",`${name} → Leura`,c?.caseRef||"",c?.id||"");}
      alert(man.send?"✓ Added and sent to Leura":"✓ Added");setMan(null);setTab("open");loadCrem();
    }catch(e){setManErr(e.message||String(e));loadCrem();}
    setManBusy(false);
  }
  return(
    <div className="max-w-3xl mx-auto px-4 py-4">
      <button onClick={onBack} className={`${s.btnGhost} w-full mb-4 py-2`}>← BACK TO HOME</button>
      <h2 className="text-xl font-black text-gray-900 mb-1">🔥 Leura Cremation Certificates</h2>
      <p className="text-sm text-gray-500 mb-4">MSS NSNA cremations at Leura Memorial Gardens. Leura is emailed a link to sign the Certificate of Cremation when the deceased is checked out.</p>
      {!man&&<button type="button" onClick={()=>{setMan(blankM);setManErr("");}} className="w-full mb-4 py-3.5 rounded-2xl border-2 border-gray-900 text-gray-900 hover:bg-gray-100 font-black uppercase tracking-wide">✏️ Add a case manually (incl. past cases)</button>}
      {man&&<div className="bg-white border-2 border-gray-900 rounded-2xl p-4 mb-4 space-y-3">
        <div className="flex items-center justify-between"><div className="font-black text-gray-900">✏️ Add a Leura cremation certificate</div><button type="button" onClick={()=>setMan(null)} className="text-sm font-bold text-gray-500 hover:text-gray-900">✕ Close</button></div>
        {!man.caseId?<div><label className={mLbl}>Find the case (name or MSL number) — optional</label>
          <input className={mInp} value={man.q} placeholder="e.g. Smith or MSL_00045" onChange={e=>setM("q",e.target.value)}/>
          {hits.length>0&&<div className="border-2 border-gray-200 rounded-xl mt-1 divide-y">{hits.map(c=><button type="button" key={c.id} onClick={()=>pickCase(c)} className="w-full text-left px-3 py-2 hover:bg-gray-50 text-sm"><b>{(c.lastName||"").toUpperCase()}, {c.firstName}</b> <span className="text-gray-400">· {c.caseRef} · {c.funeralHomeName}{c.checkedOut||c.checkout?" · checked out":""}</span></button>)}</div>}
          {man.q.trim().length>=2&&hits.length===0&&<p className="text-xs text-gray-400 mt-1">No case found. Just type the details below.</p>}</div>
        :<div className="flex items-center justify-between bg-gray-50 rounded-xl px-3 py-2 text-sm"><span>Linked to case <b>{cases.find(x=>x.id===man.caseId)?.caseRef}</b></span><button type="button" onClick={()=>setM("caseId","")} className="text-xs font-bold text-gray-500">Unlink</button></div>}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div><label className={mLbl}>First name(s) *</label><input className={mInp} value={man.firstName} onChange={e=>setM("firstName",e.target.value)}/></div>
          <div><label className={mLbl}>Surname *</label><input className={mInp} value={man.lastName} onChange={e=>setM("lastName",e.target.value)}/></div>
          <div><label className={mLbl}>Date of birth</label><input type="date" className={mInp} value={man.dob} onChange={e=>setM("dob",e.target.value)}/></div>
          <div><label className={mLbl}>Date of death *</label><input type="date" className={mInp} value={man.dod} onChange={e=>setM("dod",e.target.value)}/></div>
          <div className="sm:col-span-2"><label className={mLbl}>Funeral director *</label><select className={mInp} value={man.fhId} onChange={e=>setM("fhId",e.target.value)}><option value="">— Choose —</option>{fhList.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></div>
        </div>
        <label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={man.send} onChange={e=>setM("send",e.target.checked)} className="w-5 h-5"/> Email the signing link to Leura now</label>
        {manErr&&<div className="text-sm font-bold text-red-700 bg-red-50 rounded-xl px-3 py-2">{manErr}</div>}
        <button type="button" disabled={manBusy} onClick={saveManual} className="w-full py-3 rounded-xl bg-gray-900 hover:bg-gray-700 disabled:opacity-40 text-white font-black uppercase">{manBusy?"Saving…":man.send?"Add & send to Leura":"Add"}</button>
      </div>}
      <div className="flex gap-2 mb-4">{tabBtn("open","Waiting",all.filter(n=>!isDone(n)).length)}{tabBtn("done","Signed",all.filter(isDone).length)}</div>
      {crem2.length===0&&<p className="text-center text-sm text-gray-400 py-10">{tab==="open"?"Nothing waiting.":"No signed certificates yet."}</p>}
      <div className="space-y-2">{crem2.map(n=>{const d=n.answers?._crem||{},c=cases.find(x=>x.id===n.case_id),out=!!(c?.checkedOut||c?.checkout||d.manual);
          const pubU=p=>`${SUPABASE_URL}/storage/v1/object/public/Case-documents/${String(p).split("/").map(encodeURIComponent).join("/")}`;
          const st=d.signedAt?["✓ Signed","bg-green-100 text-green-800"]:d.sentAt?["⏳ Waiting for Leura","bg-amber-100 text-amber-800"]:out?["Not sent","bg-red-100 text-red-700"]:["In care","bg-gray-100 text-gray-600"];
          return <div key={n.id} className="bg-white border-2 border-gray-200 rounded-xl p-3 flex flex-wrap items-center gap-2 justify-between">
            <div><div className="text-sm font-black">{n.deceased_name}</div><div className="text-xs text-gray-400">{n.case_ref||"—"} · {n.funeral_home_name}{d.sentAt?` · sent ${new Date(d.sentAt).toLocaleDateString("en-AU")}`:""}{d.signedAt?` · signed ${new Date(d.signedAt).toLocaleDateString("en-AU")}${d.certNo?" · "+d.certNo:""}`:""}</div></div>
            <div className="flex flex-wrap items-center gap-2"><span className={"text-xs font-black px-2 py-1 rounded-lg "+st[1]}>{st[0]}</span>
              {d.signedAt&&<><a href={pubU(d.certPath)} target="_blank" rel="noreferrer" className="text-xs font-black uppercase px-3 py-1.5 rounded-lg border-2 border-gray-300">📄 Certificate</a>
                <button type="button" disabled={!!cremBusy} onClick={()=>cremAction(n,"resend-signed")} className="text-xs font-black uppercase px-3 py-1.5 rounded-lg border-2 border-gray-900 disabled:opacity-50">{cremBusy===n.id?"Sending…":"✉ Resend to FD"}</button></>}
              {!d.signedAt&&(out||d.sentAt)&&<button type="button" disabled={!!cremBusy} onClick={()=>cremAction(n,"request")} className="text-xs font-black uppercase px-3 py-1.5 rounded-lg border-2 border-gray-900 disabled:opacity-50">{cremBusy===n.id?"Sending…":d.sentAt?"✉ Resend to Leura":"✉ Send to Leura"}</button>}
              <button type="button" disabled={!!cremBusy} onClick={()=>cremDelete(n)} className="text-xs font-black uppercase px-3 py-1.5 rounded-lg border-2 border-red-300 text-red-700 hover:bg-red-50 disabled:opacity-50">🗑 Delete</button></div>
          </div>;})}</div>
    </div>);
}

// ─── NSNA LABELS (quick print from the Dashboard) ───────────────────────────
async function loadNsnaIds(ids){
  if(!ids.length)return new Set();
  const r=await sb(`second_notes?select=case_id&answers->>_nsna=eq.true&case_id=in.(${ids.map(id=>`"${id}"`).join(",")})`).catch(()=>[]);
  return new Set((r||[]).map(n=>n.case_id));
}
function NsnaLabelsView({user,cases,onUpdateCase,onBack}){
  const inCare=cases.filter(c=>c.status==="active").sort((a,b)=>(a.lastName||"").localeCompare(b.lastName||""));
  const [ids,setIds]=useState(null);
  const key=inCare.map(c=>c.id).join(",");
  useEffect(()=>{let live=true;loadNsnaIds(inCare.map(c=>c.id)).then(x=>{if(live)setIds(x);});return()=>{live=false;};},[key]);
  const list=ids?inCare.filter(c=>ids.has(c.id)):[];
  const printed=c=>!!c.prep?.namePlate?.label;
  const todo=list.filter(c=>!printed(c));
  async function print(cs){
    printNameLabel(cs);
    for(const c of cs){if(c.prep?.namePlate?.at)continue;const np={...(c.prep||{}),namePlate:{at:new Date().toISOString(),by:user?.name||"",label:true}};
      try{await updateCase(c.id,{prep:np});onUpdateCase(c.id,{prep:np});}catch(e){}}
  }
  const when=iso=>new Date(iso).toLocaleString("en-AU",{day:"numeric",month:"short",hour:"numeric",minute:"2-digit"});
  const blank={firstName:"",lastName:"",dob:"",dod:"",funeralHomeName:"",caseRef:""};
  const [man,setMan]=useState(null);
  const fhNames=[...new Set(cases.map(c=>c.funeralHomeName).filter(Boolean))].sort();
  const setM=(k,v)=>setMan(m=>({...m,[k]:v}));
  const inp="w-full border-2 border-gray-200 rounded-xl px-3 py-2.5 text-base focus:border-gray-900 outline-none";
  const canPrint=man&&(man.firstName.trim()||man.lastName.trim());
  return(
    <div className="max-w-3xl mx-auto px-4 py-4">
      <button onClick={onBack} className={`${s.btnGhost} w-full mb-4 py-2`}>← BACK</button>
      <h2 className="text-xl font-black text-gray-900 mb-1">🏷️ NSNA Labels</h2>
      <p className="text-sm text-gray-500 mb-4">MSS NSNA deceased in our care. Print the 6×4 name label (name, dates, funeral director) on the label printer.</p>
      {!man&&<button type="button" onClick={()=>setMan(blank)} className="w-full mb-4 py-3.5 rounded-2xl border-2 border-gray-900 text-gray-900 hover:bg-gray-100 font-black uppercase tracking-wide">✏️ Enter manually</button>}
      {man&&<div className="bg-white border-2 border-gray-900 rounded-2xl p-4 mb-4 space-y-3">
        <div className="flex items-center justify-between"><div className="font-black text-gray-900">✏️ Enter label manually</div><button type="button" onClick={()=>setMan(null)} className="text-sm font-bold text-gray-500 hover:text-gray-900">✕ Close</button></div>
        <div><label className="text-xs font-black text-gray-500 uppercase">Fill from a deceased in care (optional)</label>
          <select className={inp} value="" onChange={e=>{const c=inCare.find(x=>x.id===e.target.value);if(c)setMan({firstName:c.firstName||"",lastName:c.lastName||"",dob:(c.dob||"").slice(0,10),dod:(c.dod||"").slice(0,10),funeralHomeName:c.funeralHomeName||"",caseRef:c.caseRef||""});}}>
            <option value="">— Choose —</option>{inCare.map(c=><option key={c.id} value={c.id}>{(c.lastName||"").toUpperCase()}, {c.firstName} · {c.caseRef}</option>)}</select></div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          <div><label className="text-xs font-black text-gray-500 uppercase">First name(s)</label><input className={inp} value={man.firstName} onChange={e=>setM("firstName",e.target.value)}/></div>
          <div><label className="text-xs font-black text-gray-500 uppercase">Surname</label><input className={inp} value={man.lastName} onChange={e=>setM("lastName",e.target.value)}/></div>
          <div><label className="text-xs font-black text-gray-500 uppercase">Date of birth</label><input type="date" className={inp} value={man.dob} onChange={e=>setM("dob",e.target.value)}/></div>
          <div><label className="text-xs font-black text-gray-500 uppercase">Date of death</label><input type="date" className={inp} value={man.dod} onChange={e=>setM("dod",e.target.value)}/></div>
          <div className="sm:col-span-2"><label className="text-xs font-black text-gray-500 uppercase">Funeral director</label><input className={inp} list="nsna-fh" value={man.funeralHomeName} onChange={e=>setM("funeralHomeName",e.target.value)}/><datalist id="nsna-fh">{fhNames.map(n=><option key={n} value={n}/>)}</datalist></div>
          <div className="sm:col-span-2"><label className="text-xs font-black text-gray-500 uppercase">Ref (optional)</label><input className={inp} value={man.caseRef} onChange={e=>setM("caseRef",e.target.value)}/></div>
        </div>
        <div className="flex gap-2">
          <button type="button" disabled={!canPrint} onClick={()=>printNameLabel(man)} className="flex-1 py-3 rounded-xl bg-gray-900 hover:bg-gray-700 disabled:opacity-40 text-white font-black uppercase">🏷️ Print label</button>
          <button type="button" onClick={()=>setMan(blank)} className="px-4 py-3 rounded-xl border-2 border-gray-300 font-black uppercase text-sm text-gray-700">Clear</button>
        </div>
      </div>}
      {todo.length>1&&<button type="button" onClick={()=>print(todo)} className="w-full mb-4 py-3.5 rounded-2xl bg-gray-900 hover:bg-gray-700 text-white font-black uppercase tracking-wide">🏷️ Print all {todo.length} not yet printed</button>}
      {!ids&&<p className="text-center text-sm text-gray-400 py-10">Loading…</p>}
      {ids&&list.length===0&&<p className="text-center text-sm text-gray-400 py-10">No MSS NSNA deceased in our care.</p>}
      <div className="space-y-2">{list.map(c=>(
        <div key={c.id} className={"bg-white border-2 rounded-2xl px-4 py-3 flex flex-wrap items-center gap-3 "+(printed(c)?"border-green-300":"border-gray-200")}>
          <div className="flex-1 min-w-0"><div className="text-lg font-black text-gray-900">{(c.lastName||"").toUpperCase()}, {c.firstName}</div>
            <div className="text-sm text-gray-500">{c.caseRef} · {c.funeralHomeName}</div>
            {printed(c)&&<div className="text-xs font-black text-green-700 mt-1">✓ Printed {when(c.prep.namePlate.at)}{c.prep.namePlate.by?" · "+c.prep.namePlate.by:""}</div>}</div>
          <button type="button" onClick={()=>print([c])} className={"px-5 py-3 rounded-xl font-black uppercase text-sm "+(printed(c)?"border-2 border-gray-300 text-gray-700 hover:border-gray-900":"bg-gray-900 hover:bg-gray-700 text-white")}>{printed(c)?"↻ Reprint":"🏷️ Print"}</button>
        </div>))}</div>
    </div>);
}

// ─── NAME PLATES (all cases in care) ─────────────────────────────────────────
function NamePlatesView({user,cases,onUpdateCase,onBack}){
  const inCare=cases.filter(c=>c.status==="active").sort((a,b)=>(a.lastName||"").localeCompare(b.lastName||""));
  const [plates,setPlates]=useState({});const [open,setOpen]=useState(null);const [tab,setTab]=useState("todo");const [q,setQ]=useState("");
  const [pick,setPick]=useState(null); // "+ New Name Plate": choose the funeral director, then the deceased
  const [nsna,setNsna]=useState({}); // MSS NSNA cases get a printed name label instead of an engraved plate
  const idKey=inCare.map(c=>c.id).join(",");
  useEffect(()=>{if(!idKey)return;let live=true;
    sb(`second_notes?select=case_id,answers,submitted_at&case_id=in.(${inCare.map(c=>`"${c.id}"`).join(",")})&order=submitted_at.desc`).then(r=>{if(!live||!Array.isArray(r))return;const m={};r.forEach(n=>{if(!(n.case_id in m))m[n.case_id]=n.answers?._plate||null;});inCare.forEach(c=>{if(!(c.id in m))m[c.id]=null;});setPlates(m);const ns={};r.forEach(n=>{if(!(n.case_id in ns))ns[n.case_id]=n.answers?._nsna===true;});setNsna(ns);}).catch(()=>{});
    return()=>{live=false;};},[idKey]);
  async function mark(c,plate,person){const np={...(c.prep||{}),namePlate:{at:new Date().toISOString(),by:user?.name||"",plate,person}};try{await updateCase(c.id,{prep:np});onUpdateCase(c.id,{prep:np});setOpen(o=>o&&o.c.id===c.id?{...o,c:{...o.c,prep:np}}:o);}catch(e){alert("Couldn't record the download: "+e.message);}}
  async function printLabel(c){printNameLabel(c);if(c.prep?.namePlate?.at)return;const np={...(c.prep||{}),namePlate:{at:new Date().toISOString(),by:user?.name||"",label:true}};try{await updateCase(c.id,{prep:np});onUpdateCase(c.id,{prep:np});}catch(e){}}
  async function markNone(c,undo){
    const np={...(c.prep||{})};if(undo)delete np.namePlate;else np.namePlate={at:new Date().toISOString(),by:user?.name||"",none:true};
    try{await updateCase(c.id,{prep:np});onUpdateCase(c.id,{prep:np});}catch(e){alert("Couldn't save: "+(e.message||e));}}
  const done=c=>!!c.prep?.namePlate?.at;
  const todo=inCare.filter(c=>!done(c)),dl=inCare.filter(done);
  const completed=cases.filter(c=>c.prep?.namePlate?.at).sort((a,b)=>new Date(b.prep.namePlate.at)-new Date(a.prep.namePlate.at));
  const qq=q.trim().toLowerCase();
  const compShown=qq?completed.filter(c=>`${c.firstName} ${c.lastName} ${c.caseRef} ${c.funeralHomeName}`.toLowerCase().includes(qq)):completed;
  const list=tab==="todo"?todo:tab==="done"?dl:inCare;
  const when=iso=>new Date(iso).toLocaleString("en-AU",{day:"numeric",month:"short",year:"numeric",hour:"numeric",minute:"2-digit"});
  const tabBtn=(k,l,n)=><button type="button" onClick={()=>setTab(k)} className={"px-4 py-2.5 rounded-xl border-2 text-sm font-black transition "+(tab===k?"bg-gray-900 border-gray-900 text-white":"bg-white border-gray-200 text-gray-700 hover:border-gray-700")}>{l} · {n}</button>;
  const rec=c=>c.prep?.namePlate||{};
  return(
    <div className="max-w-4xl mx-auto px-4 py-4">
      <button onClick={onBack} className={`${s.btnGhost} w-full mb-4 py-2`}>← BACK TO HOME</button>
      <h2 className="text-xl font-black text-gray-900 mb-1">🪧 Name Plates</h2>
      <p className="text-sm text-gray-500 mb-4">Every deceased in our care. Open one to check the plate and download it for xTool. A case leaves the in-care lists once the body is checked out; <b>Completed</b> keeps the final version of every plate.</p>
      <button type="button" onClick={()=>setPick({fh:null})} className="w-full mb-4 py-3.5 rounded-2xl bg-green-600 hover:bg-green-700 text-white font-black uppercase tracking-wide">+ New Name Plate</button>
      {pick&&(()=>{const fhs=[...new Map(inCare.map(c=>[c.funeralHomeId,{id:c.funeralHomeId,name:c.funeralHomeName||"Other"}])).values()].sort((a,b)=>a.name.localeCompare(b.name));
        const mine=pick.fh?inCare.filter(c=>c.funeralHomeId===pick.fh.id):[];
        return(<div className="fixed inset-0 z-50 bg-black/50 flex items-start justify-center p-3 overflow-y-auto" onClick={()=>setPick(null)}>
          <div className="bg-white rounded-2xl w-full max-w-2xl p-5 my-6" onClick={e=>e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4"><div className="text-lg font-black">{pick.fh?pick.fh.name:"+ New Name Plate"}</div>
              <button type="button" onClick={()=>pick.fh?setPick({fh:null}):setPick(null)} className="px-3 py-1.5 rounded-lg border-2 border-gray-300 text-sm font-black">{pick.fh?"‹ Back":"✕"}</button></div>
            {!pick.fh?<>
              <p className="text-xs font-black uppercase tracking-widest text-gray-500 mb-2">1. Funeral director</p>
              {fhs.length===0&&<p className="text-sm text-gray-400 py-6 text-center">No deceased in our care.</p>}
              <div className="grid sm:grid-cols-2 gap-2">{fhs.map(f=>{const n=inCare.filter(c=>c.funeralHomeId===f.id).length;return(
                <button key={f.id} type="button" onClick={()=>setPick({fh:f})} className="text-left px-4 py-3 rounded-xl border-2 border-gray-200 hover:border-gray-900 font-black text-sm">{f.name}<span className="block text-xs font-bold text-gray-500">{n} in our care</span></button>);})}</div>
            </>:<>
              <p className="text-xs font-black uppercase tracking-widest text-gray-500 mb-2">2. Deceased</p>
              <div className="space-y-2">{mine.map(c=>(
                <button key={c.id} type="button" onClick={()=>{setPick(null);setOpen({c,plate:rec(c).plate||plates[c.id]||null});}} className="w-full text-left px-4 py-3 rounded-xl border-2 border-gray-200 hover:border-gray-900 flex items-center gap-3">
                  <div className="flex-1"><div className="font-black">{(c.lastName||"").toUpperCase()}, {c.firstName}</div><div className="text-xs text-gray-500">{c.caseRef}</div></div>
                  <span className={"text-[10px] font-black uppercase px-2 py-1 rounded-full "+(done(c)?"bg-green-100 text-green-800":"bg-red-50 text-red-700")}>{done(c)?(rec(c).none?"No plate needed":"Downloaded"):"Not done"}</span>
                </button>))}</div>
            </>}
          </div>
        </div>);})()}
      <div className="flex flex-wrap gap-2 mb-4">{tabBtn("todo","To do",todo.length)}{tabBtn("done","Downloaded / Done",dl.length)}{tabBtn("all","All in care",inCare.length)}{tabBtn("completed","✓ Completed",completed.length)}</div>
      {tab!=="completed"&&<>
        {list.length===0&&<p className="text-center text-sm text-gray-400 py-10">{tab==="todo"?"All name plates are done.":"Nothing here."}</p>}
        <div className="space-y-2">{list.map(c=>{const p=plates[c.id],none=!!rec(c).none;return(
          <div key={c.id} className="flex items-stretch gap-2">
          <button type="button" onClick={()=>setOpen({c,plate:rec(c).plate||p||null})} className={"w-full text-left bg-white border-2 rounded-2xl px-4 py-3 flex flex-wrap items-center gap-x-4 gap-y-2 transition hover:border-gray-900 "+(done(c)?"border-green-300":"border-gray-200")}>
            <div className="min-w-0 flex-1">
              <div className="text-lg font-black text-gray-900">{(c.lastName||"").toUpperCase()}, {c.firstName}</div>
              <div className="text-sm text-gray-500">{c.caseRef} · {c.funeralHomeName}{nsna[c.id]&&<span className="ml-2 text-[10px] font-black uppercase px-2 py-0.5 rounded-full bg-gray-900 text-white">MSS NSNA</span>}</div>
            </div>
            <span className={"text-xs font-black px-3 py-1.5 rounded-full "+(p?"bg-gray-100 text-gray-700":"bg-amber-50 text-amber-800")}>{p===undefined?"…":p?"From 2nd Note":"No plate on 2nd Note"}</span>
            <span className={"text-xs font-black px-3 py-1.5 rounded-full "+(done(c)?"bg-green-100 text-green-800":"bg-red-50 text-red-700")}>{done(c)?`✓ ${none?"No plate needed":rec(c).label?"Label printed":"Downloaded"} ${when(rec(c).at)}${rec(c).by?" · "+rec(c).by:""}`:"Not downloaded"}</span>
          </button>
          {nsna[c.id]&&<button type="button" onClick={()=>printLabel(c)} className="shrink-0 w-28 rounded-2xl bg-gray-900 hover:bg-gray-700 text-white text-xs font-black uppercase leading-tight px-2">🏷️ Print label<span className="block text-[10px] font-bold normal-case opacity-80">NSNA name label</span></button>}
          {!done(c)&&<button type="button" onClick={()=>markNone(c)} className="shrink-0 w-28 rounded-2xl bg-green-600 hover:bg-green-700 text-white text-xs font-black uppercase leading-tight px-2">✓ Completed<span className="block text-[10px] font-bold normal-case opacity-90">No plate needed</span></button>}
          {none&&<button type="button" onClick={()=>markNone(c,true)} className="shrink-0 w-28 rounded-2xl border-2 border-gray-300 bg-white hover:border-gray-900 text-gray-700 text-xs font-black uppercase">↩ Undo</button>}
          </div>);})}</div>
      </>}
      {tab==="completed"&&<>
        <input className={`${s.inp} mb-4`} value={q} onChange={e=>setQ(e.target.value)} placeholder="Search by name, case number or funeral director…"/>
        {compShown.length===0&&<p className="text-center text-sm text-gray-400 py-10">{completed.length?"No match.":"No name plates downloaded yet."}</p>}
        <div className="grid sm:grid-cols-2 gap-3">{compShown.map(c=>{const r=rec(c),person=r.person||{firstName:c.firstName,lastName:c.lastName,dob:c.dob,dod:c.dod};return(
          <button key={c.id} type="button" onClick={()=>setOpen({c,plate:r.plate||null,person})} className="text-left bg-white border-2 border-gray-200 rounded-2xl p-3 hover:border-gray-900 transition">
            <div className="flex items-start justify-between gap-2 mb-2">
              <div className="min-w-0"><div className="font-black text-gray-900">{(c.lastName||"").toUpperCase()}, {c.firstName}</div>
                <div className="text-xs text-gray-500">{c.caseRef} · {c.funeralHomeName}</div></div>
              <span className={"shrink-0 text-[10px] font-black uppercase px-2 py-1 rounded-full "+(c.status==="active"?"bg-amber-50 text-amber-800":"bg-gray-100 text-gray-600")}>{c.status==="active"?"In care":"Checked out"}</span>
            </div>
            {r.none?<p className="text-sm font-black text-gray-500 py-6 text-center bg-gray-50 rounded-xl">No name plate needed</p>:r.label?<p className="text-sm font-black text-gray-500 py-6 text-center bg-gray-50 rounded-xl">🏷️ NSNA name label printed</p>:r.plate?<NamePlatePreview spec={{...r.plate,...person}}/>:<p className="text-xs text-gray-400 py-6 text-center">Downloaded before plate records were kept</p>}
            <div className="text-xs font-black text-green-700 mt-2">✓ {r.none?"Completed – no plate":"Final version"} · {when(r.at)}{r.by?" · "+r.by:""}</div>
          </button>);})}</div>
      </>}
      {open&&<NamePlateModal c={open.c} plate={open.plate} person={open.person} onClose={()=>setOpen(null)} onDownloaded={(pl,pe)=>mark(open.c,pl,pe)}/>}
    </div>
  );
}

